/* =========================================================================
   MANUAL DE USO — contenido
   -------------------------------------------------------------------------
   ESTE ARCHIVO ES LA FUENTE DE VERDAD DEL MANUAL. Se edita aca, no en el Word.

   De aca salen cuatro derivados, y van al reves de lo que decia este
   comentario hasta el 30-08-2026:

     manual-a-word.py  ->  AFAAR - Manual de uso (socios).docx
                           AFAAR - Manual de uso, alcances y capacidad (ampliado).docx
     y de esos dos Word se exportan los dos PDF que sirve la app.

   build.py llama a manual-a-word.py solo cuando este archivo quedo mas nuevo
   que los .docx. Nunca editar los .docx a mano: se pisan en la siguiente
   reconstruccion.

   El capitulo con coord:true lo ve unicamente la coordinacion (misma regla
   que capitulosManual() en ui-manual.js), y por eso los dos Word son
   distintos: el de socios no lleva el anexo de administracion de la base.
   ========================================================================= */
const MANUAL = [{"n": "", "tit": "Qué es esta aplicación", "ico": "info", "coord": false, "b": [{"t": "p", "txt": "AFAAR es una aplicación web que acompaña el acto médico anestesiológico de punta a punta: desde la consulta prequirúrgica hasta la firma del registro, pasando por el consentimiento informado, el registro intraoperatorio, la recuperación, la facturación y las estadísticas."}, {"t": "p", "txt": "Funciona en cualquier computadora, tablet o teléfono, sin instalar nada. Se abre desde https://claudioravasi-ai.github.io/afar/ y se puede agregar a la pantalla de inicio para que quede con su ícono, a pantalla completa y sin barra del navegador."}, {"t": "p", "txt": "Todo lo que carga cualquier socio aparece en el resto de los dispositivos en segundos, porque los datos viven en una base compartida en la nube."}, {"t": "img", "src": "manual/m1.jpg"}, {"t": "h2", "txt": "Lo que hay que leer sí o sí"}, {"t": "li", "num": false, "txt": "El <b>capítulo 10, Seguridad</b>: qué protege y qué no."}, {"t": "li", "num": false, "txt": "El <b>capítulo 12, Capacidad</b>: qué volumen soporta la aplicación, con las mediciones hechas sobre ella funcionando."}, {"t": "li", "num": false, "txt": "El <b>capítulo 11, Pendientes</b>: lo que falta antes del uso asistencial pleno."}]}, {"n": "1", "tit": "Quién entra y cómo", "ico": "usuario", "coord": false, "b": [{"t": "tabla", "head": ["Perfil", "Cómo entra", "Qué ve"], "rows": [["<b>Anestesiólogo (socio)</b>", "Su correo y su contraseña, elegidos por él al registrarse", "Sólo los pacientes en los que intervino, su facturación y sus estadísticas"], ["<b>Coordinador</b>", "Credencial única de coordinación", "Todo: socios, padrón completo, catálogos, prestadores y auditoría"], ["<b>Contable</b>", "Credencial única del contable", "Sólo lo económico. Ningún dato clínico de ningún paciente"]]}, {"t": "aviso", "clase": "info", "tit": "<b>La versión, al pie de la pantalla de ingreso</b>", "cuerpo": ["Abajo de todo, en gris chico, dice <b>Versión 2026.08.30.0833</b> o la que corresponda. Sirve para lo de siempre con las aplicaciones web: saber si el navegador está sirviendo la última o una copia vieja de su caché. Si no coincide con la que anunció la coordinación, hay que recargar forzando —Cmd+Shift+R en Mac, Ctrl+F5 en Windows—."]}, {"t": "h2", "txt": "El alta de un anestesiólogo, paso a paso"}, {"t": "li", "num": true, "txt": "En la pantalla de ingreso, tocar la pestaña <b>Registrarme</b>."}, {"t": "li", "num": true, "txt": "Cargar apellido, nombre, DNI, correo, una contraseña propia, matrícula nacional y provincial, y el comprobante de socio de la asociación."}, {"t": "li", "num": true, "txt": "La solicitud queda en estado <b>pendiente</b>. No se puede entrar todavía."}, {"t": "li", "num": true, "txt": "El coordinador entra a <b>Coordinación → Solicitudes</b>, verifica la matrícula y el comprobante, y aprueba."}, {"t": "li", "num": true, "txt": "Desde ese momento el socio entra desde cualquier dispositivo del mundo con su correo y su contraseña."}, {"t": "p", "txt": "Nadie se auto-habilita. Ese paso de aprobación es lo que impide que una persona ajena a la asociación se cree una cuenta y acceda a historias clínicas."}, {"t": "h2", "txt": "Las claves del coordinador y del contable"}, {"t": "p", "txt": "Son claves únicas, compartidas dentro de cada función."}]}, {"n": "2", "tit": "Puesta a punto inicial", "ico": "ajustes", "coord": false, "b": [{"t": "p", "txt": "Este capítulo es nuevo y existe por una razón concreta: entre instalar la aplicación y atender al primer paciente real hay una secuencia de tareas que le corresponden a la coordinación, y que si se saltean se notan tarde y mal —honorarios en cero, financiadores duplicados, estadísticas que cuentan cirugías que nunca existieron—."}, {"t": "p", "txt": "Es trabajo de una tarde, se hace una sola vez y conviene hacerlo en este orden."}, {"t": "h2", "txt": "La secuencia"}, {"t": "tabla", "head": ["", "Qué", "Dónde", "Por qué va en este lugar"], "rows": [["1", "Recorrer la aplicación con los datos de demostración", "Coordinación → Catálogos → Cargar datos de demostración", "Para entender las pantallas antes de cargar nada real"], ["2", "Cargar las instituciones", "Coordinación → Prestadores", "La ficha las pide en el paso 1 y no se pueden inventar al vuelo"], ["3", "Cargar los financiadores", "Coordinación → Prestadores", "Llevan el valor de la unidad anestésica, que es la base del honorario"], ["4", "Cargar el valor de la unidad por financiador", "Coordinación → Catálogos", "Sin esto, cada honorario del acto sale en cero"], ["5", "Aprobar las altas de los socios", "Coordinación → Solicitudes", "Recién acá los anestesiólogos pueden entrar"], ["6", "Cargar el IPC y confirmar la escala fiscal", "Portal contable → Parámetros", "Todo el portal contable se apoya en estos dos datos"], ["7", "Borrar la demostración de <b>todos</b> los equipos", "Coordinación → Catálogos, o el cartel amarillo del inicio", "Es lo último, y es lo que más se olvida"], ["8", "Descargar el primer respaldo", "Indicador del encabezado → Descargar respaldo", "Deja un punto de partida al que volver"]]}, {"t": "h2", "txt": "2.1 · Instituciones y financiadores"}, {"t": "p", "txt": "Se cargan en <b>Coordinación → Prestadores</b>. Toda la fila de la tabla es un botón: se edita haciendo clic en cualquier renglón."}, {"t": "p", "txt": "<b>De una institución</b> se guarda: nombre, ciudad, tipo, CUIT, teléfono, contacto de jefatura o de facturación, correo, domicilio y notas."}, {"t": "p", "txt": "<b>De un financiador</b> se guarda: nombre, CUIT, plazo de pago, contacto de auditoría, teléfono, correo para presentaciones, domicilio, notas del convenio y —lo que gobierna la facturación— el <b>valor de la unidad anestésica</b> y el <b>valor de la consulta prequirúrgica</b>."}, {"t": "aviso", "clase": "info", "tit": "<b>Detector de duplicados</b>", "cuerpo": ["Si alguien cargó «OSDE» y otro «O.S.D.E.», la aplicación lo detecta y ofrece fusionarlos —todas las fichas y pacientes pasan al nombre elegido— o marcarlos como distintos. Conviene revisar este aviso antes de dar por cerrada la carga."]}, {"t": "h2", "txt": "2.2 · El valor de la unidad anestésica"}, {"t": "p", "txt": "Se carga en <b>Coordinación → Catálogos</b>, en la primera tarjeta. Hay un <b>valor por defecto</b> y una tabla financiador por financiador; el valor específico manda sobre el general."}, {"t": "p", "txt": "Ese número se aplica solo al abrir la solapa de honorarios de cada ficha. Si el financiador de la ficha no tiene valor cargado, el cálculo da cero y la propia ficha lo avisa: <i>«No hay valor de unidad cargado para este financiador. El coordinador puede definirlo en Catálogos para que se complete solo»</i>."}, {"t": "p", "txt": "Es la diferencia entre que la facturación salga sola y que veinte personas tengan que escribir a mano el mismo número todos los días."}, {"t": "img", "src": "manual/m2.jpg"}, {"t": "h2", "txt": "2.3 · Lo que ya viene cargado"}, {"t": "p", "txt": "No hay que cargar catálogos clínicos: la aplicación trae de base:"}, {"t": "li", "num": false, "txt": "<b>1.477 prácticas</b> del nomenclador anestésico AFAAR, en 19 grupos."}, {"t": "li", "num": false, "txt": "<b>725 procedimientos</b> quirúrgicos precargados."}, {"t": "li", "num": false, "txt": "<b>98 antecedentes</b> patológicos."}, {"t": "li", "num": false, "txt": "<b>64 fármacos</b> en el vademécum, de adultos y pediatría, en 13 grupos."}, {"t": "li", "num": false, "txt": "<b>15 guías</b> y protocolos de consulta rápida."}, {"t": "p", "txt": "Los socios pueden agregar antecedentes y cirugías que falten; lo agregado a mano queda listado en Coordinación → Catálogos, para que la coordinación lo revise y decida si corresponde incorporarlo al catálogo de base."}, {"t": "h2", "txt": "2.4 · Borrar la demostración: el paso que se olvida"}, {"t": "p", "txt": "La aplicación trae seis anestesiólogos de ejemplo con pacientes y fichas en distintos estados —valoraciones sin acto, actos sin honorarios, deuda vieja sin cobrar, una solicitud de alta pendiente y un reclamo sin responder— para recorrer la aplicación entera."}, {"t": "aviso", "clase": "danger", "tit": "<b>Los datos de demostración son por dispositivo</b>", "cuerpo": ["Llevan una marca interna y nunca viajan a la nube: existen sólo en el equipo donde se cargaron. Eso tiene dos consecuencias. La primera es buena: no ensucian la base compartida. La segunda hay que tenerla presente: <b>borrarlos de un equipo no los borra de los demás</b>. Antes del primer paciente real hay que borrarlos en cada equipo donde se hayan cargado, o las estadísticas van a contar cirugías que nunca existieron.", "La paciente de prueba de la reintervención", "Entre los datos de demostración hay una paciente puesta a propósito para probar el circuito de reintervención: <b>Ledesma, Ana Clara — DNI 27655310</b>, con una colecistectomía ya valorada por una colega y con el <b>consentimiento firmado</b>.", "Es la única valoración completa de la demostración: las demás fichas de ejemplo tienen el consentimiento sin firmar, y por eso no se ofrecen para importar. Con ella se recorre todo: nueva ficha anestésica, tomar el acto, <i>ya fue valorado para una intervención anterior</i>, importar y firmar el consentimiento nuevo.", "Si la demostración ya estaba cargada de antes, aparece en <b>Coordinación → Catálogos</b> un aviso diciendo que falta, con el botón <b>Completar la demostración</b>. De lo contrario debe <b>Cargar Demostración</b>."]}, {"t": "p", "txt": "Se borran desde <b>Coordinación → Catálogos → Borrar la demostración</b>, o desde el cartel amarillo que aparece en la pantalla de inicio mientras haya datos de ejemplo cargados."}, {"t": "img", "src": "manual/m3.jpg"}, {"t": "h2", "txt": "2.5 · Dónde se carga la cobertura"}, {"t": "p", "txt": "La ventana de <b>Nuevo paciente</b> ya no pide obra social ni número de afiliado. La cobertura se elige en cada ficha, en <b>Datos de la cirugía</b> del paso 1, porque es de la intervención y no de la persona: el mismo paciente se opera una vez por su obra social y la siguiente como particular. Además, en la ficha está el botón <b>Agregar otro financiador</b> —que en la ventana del paciente no existía— y el campo de número de autorización, que sólo tiene sentido para esa intervención."}, {"t": "p", "txt": "Lo que se elige en la ficha <b>vuelve solo a la historia del paciente</b>: la ficha siguiente lo propone y la ventana del paciente lo muestra como dato de referencia, sin poder editarlo. Los pacientes que ya tenían cobertura cargada la conservan."}]}, {"n": "3", "tit": "El anestesiólogo, paso a paso", "ico": "valoracion", "coord": false, "b": [{"t": "p", "txt": "La ficha es un recorrido de cinco pasos, en el mismo orden en que ocurre el acto médico. Cada paso se pinta solo con uno de cuatro colores, con el rótulo escrito debajo del punto, para saber de un vistazo si el registro está en condiciones de firmarse."}, {"t": "tabla", "head": ["Color", "Rótulo", "Significa"], "rows": [["<b>Verde</b>", "Completo", "No falta nada de lo esencial"], ["<b>Ámbar</b>", "A medias", "Empezado, falta algo para darlo por cerrado"], ["<b>Rojo</b>", "Falta", "Empezado y falta algo que no se puede omitir"], ["<b>Gris</b>", "Pendiente", "Todavía sin tocar"]]}, {"t": "img", "src": "manual/m4.jpg"}, {"t": "h2", "txt": "Paso 1 · Paciente"}, {"t": "p", "txt": "Identificación del paciente y datos del procedimiento."}, {"t": "li", "num": false, "txt": "Se elige el paciente del padrón o se crea uno nuevo."}, {"t": "li", "num": false, "txt": "Si el acto se declaró como <b>reintervención</b>, el paciente <b>no se elige acá</b>: viene de la ficha que se importó y aparece con candado, sin desplegable y sin «crear paciente nuevo». Es la misma persona por definición, y dejar el desplegable abierto permitía terminar con la valoración de un paciente y los datos de otro. Lo que sí se puede es <b>editar su historia clínica</b>: la reintervención ocurre con el paciente internado y en evolución, así que el peso, la medicación y los antecedentes cambiaron desde aquella valoración."}, {"t": "li", "num": false, "txt": "Peso y talla, con IMC calculado solo. <b>El peso es obligatorio</b>: sin él, el vademécum no propone ninguna dosis."}, {"t": "li", "num": false, "txt": "<b>Carácter con el que se plantea la cirugía en esta consulta</b>: programada, urgencia o emergencia. El rótulo decía «carácter de la cirugía» y la ayuda de abajo decía «carácter de la consulta»: eran dos nombres para el mismo campo y ninguno exacto. Son <b>dos carácteres y los dos son de la cirugía</b> —éste es cómo se la ve hoy, en la consulta, y alimenta el ARISCAT que se imprime en la valoración; el otro es cómo se la terminó anestesiando, se confirma el día del acto en el paso 3, y es el que se informa y el que se factura—."}, {"t": "li", "num": false, "txt": "Institución, <b>financiador y número de afiliado o autorización</b>. La cobertura se carga <b>acá y sólo acá</b>: se sacó de la ventana de «Nuevo paciente» porque la obra social es de la intervención, no de la persona —el mismo paciente se opera una vez por su obra social y la siguiente como particular—. Además, acá está el botón <b>Agregar otro financiador</b>, que en la ventana del paciente no existía. Lo que se elija vuelve solo a la historia del paciente para que la ficha siguiente lo proponga."}, {"t": "li", "num": false, "txt": "Diagnóstico en texto claro y <b>una o varias cirugías</b> buscadas en el nomenclador anestésico AFAAR (1.477 prácticas, 19 grupos). Si en el mismo acto se hace más de un procedimiento, se agregan todos: cada uno queda con su vía de abordaje y con el porcentaje con el que se factura."}, {"t": "h3", "txt": "Más de una cirugía en el mismo acto"}, {"t": "p", "txt": "El buscador de procedimientos ya no acepta una sola práctica: se agregan todas las que se hagan en el mismo acto anestésico. Antes sólo entraba una, y la segunda no quedaba registrada en ningún lado ni se facturaba."}, {"t": "p", "txt": "Cada procedimiento agregado muestra su código, su complejidad, su <b>vía de abordaje</b> y el <b>porcentaje</b> con el que corresponde facturarlo, según la regla del nomenclador:"}, {"t": "tabla", "head": ["Procedimiento", "Se factura al", "Cuándo"], "rows": [["<b>El de mayor complejidad</b>", "<b>100 %</b>", "Siempre. Es el principal."], ["Cada procedimiento adicional", "<b>75 %</b>", "Cuando su vía de abordaje es <b>distinta</b> de la del principal. Ejemplo: colecistectomía + fimosis."], ["Cada procedimiento adicional", "<b>50 %</b>", "Cuando comparte la <b>misma</b> vía que el principal. Ejemplo: colecistectomía laparoscópica + gastrostomía laparoscópica."]]}, {"t": "p", "txt": "La vía la <b>propone la aplicación leyendo el nombre de la práctica en el nomenclador</b>: «Colecistectomía laparoscópica» da laparoscópica, «Colecistectomía simple» da abierta abdominal, «Fimosis y parafimosis» da cutánea. Cuando el nombre no la dice, la deduce de la región anatómica. Reconoce la vía en unas 1.040 de las 1.477 prácticas; en el resto queda «Sin declarar» y la aplicación lo avisa, porque sin ese dato no se puede decidir entre el 75 % y el 50 %. En todos los casos hay un desplegable al lado de cada procedimiento para corregirla, y el porcentaje se recalcula en el acto."}, {"t": "aviso", "clase": "info", "tit": "<b>El principal lo propone la aplicación, lo decide el anestesiólogo</b>", "cuerpo": ["La aplicación marca como principal al de mayor complejidad —y a igual complejidad, al de más unidades anestésicas—. Si corresponde otro, el botón <b>Principal</b> de cada renglón lo cambia y todos los porcentajes se recalculan. Un porcentaje puesto por la máquina en una factura que firma un médico tiene que poder verse y cambiarse."]}, {"t": "p", "txt": "En <b>Honorarios</b>, cuando hay más de un procedimiento, aparece una fila por cada uno para cargar sus unidades anestésicas. La base del cálculo pasa a ser la suma de las UA de cada procedimiento afectadas por su porcentaje: 20 UA al 100 % + 12 UA al 75 % + 8 UA al 75 % dan <b>35 UA efectivas</b>. El detalle renglón por renglón queda guardado en la ficha y sale en la exportación al contador, en dos columnas nuevas: <i>Procedimientos</i> y <i>Detalle 100/75/50 %</i>. Es la respuesta escrita a la pregunta que hace toda auditoría: de dónde salieron las unidades de esa factura."}, {"t": "p", "txt": "Los documentos impresos —la valoración, el consentimiento y las indicaciones al paciente— nombran <b>todos</b> los procedimientos, no sólo el principal. Un consentimiento que menciona una cirugía cuando se hicieron tres no cubre las otras dos."}, {"t": "p", "txt": "No se piden fecha, hora ni turno. Cuando el anestesiólogo hace la valoración, la cirugía todavía no está programada. La fecha real del acto se carga el día de la cirugía, en el paso 3."}, {"t": "p", "txt": "Abajo hay un solo botón, <b>Siguiente</b>, que guarda solo lo cargado y avanza."}, {"t": "h2", "txt": "Las dos puertas para que el paciente cargue sus datos"}, {"t": "p", "txt": "La aplicación tiene <b>dos caminos</b> para que el paciente complete su ficha antes de venir, y conviene no confundirlos: uno lo abrís vos para alguien que ya tenés cargado, y el otro lo abre el paciente por su cuenta."}, {"t": "tabla", "head": ["", "Por invitación", "Precarga abierta"], "rows": [["<b>Quién empieza</b>", "Vos, desde una ficha", "El paciente, desde una dirección pública"], ["<b>Cuándo sirve</b>", "Ya tenés al paciente y la ficha abierta", "Todavía no existe en la aplicación"], ["<b>Qué completa</b>", "Filiación y salud", "Filiación, salud <b>y su turno</b>, con foto del ticket"], ["<b>Dónde aparece</b>", "En esa ficha, paso Paciente", "En Pacientes → Precargados, como agenda"]]}, {"t": "p", "txt": "Lo que <b>no</b> cambia entre los dos: en ninguno de los dos lo que escribe el paciente entra solo en su historia clínica. Siempre pasa por la misma revisión campo por campo."}, {"t": "h3", "txt": "Mandarle la ficha al paciente para que la complete"}, {"t": "p", "txt": "Al lado de <b>Siguiente</b>, en este paso <b>Paciente</b>, hay un botón: <b>Enviarle la ficha por mail</b>. Le manda al paciente un <b>enlace personal</b> para que complete su parte desde el teléfono o la computadora, antes de venir. No hay PDF ni papel: escribe directamente en la aplicación y lo que carga llega a esta ficha."}, {"t": "p", "txt": "El enlace le abre <b>dos pantallas y nada más</b>: sus datos de filiación y las preguntas de salud que puede contestar él —qué enfermedades tuvo, qué operaciones se hizo, cómo le fue con anestesias anteriores, qué toma, a qué es alérgico, sus hábitos—. No ve la aplicación, no ve otras fichas, no ve otros pacientes, y no puede llegar al examen físico, las escalas, el plan ni el consentimiento. En modo paciente la aplicación entera queda oculta."}, {"t": "p", "txt": "Debajo de <b>PACIENTE</b>, en la barra de pasos, queda el sello del pedido: <i>«Pendiente: se envió ficha por mail»</i> mientras no contesta, y <i>«El paciente completó la ficha»</i> cuando toca FINALIZADO. El cambio se ve sin recargar nada."}, {"t": "aviso", "clase": "warn", "tit": "<b>Lo que el paciente escribe no entra solo en su historia</b>", "cuerpo": ["Es lo más importante de esta función. Cuando el paciente finaliza, aparece un botón <b>Revisar lo que cargó</b> que abre una lista campo por campo: lo que ya había contra lo que propone el paciente, todo tildado y todo destildable. Sólo se incorpora a la historia clínica lo que quede marcado.", "Una historia clínica la escribe un profesional. El paciente aporta, no redacta. Y evita el problema obvio: el paciente que se confunde y dice que no toma anticoagulantes.", "La medicación que se incorpora entra con su conducta perioperatoria ya puesta desde el vademécum, y queda marcada como <i>referida por el paciente</i>."]}, {"t": "p", "txt": "El enlace <b>vence a los 30 días</b> y, una vez que el paciente finaliza, deja de poder escribir: si hay que corregir algo, se manda un pedido nuevo, y el anterior queda sin efecto."}, {"t": "aviso", "clase": "info", "tit": "<b>Qué hace falta para que esto funcione</b>", "cuerpo": ["Tres cosas: que el <b>envío de mails</b> esté configurado (ver ENVIO-DE-MAILS.md), que la base compartida esté <b>en línea</b> —el indicador de arriba tiene que decir «En línea»— y que estén pegadas en la consola de Firebase las reglas de la rama <b>afar-prellenado</b> (ver reglas-firebase.txt). Sin las reglas el envío falla con «La base rechazó el pedido» y no se rompe nada más.", "El correo del paciente pasó a ser <b>obligatorio</b> en sus datos de filiación, justamente porque toda la documentación que la aplicación le entrega viaja por ahí. La única excepción es el NN provisional de una urgencia, que se abre sin identidad."]}, {"t": "p", "txt": "La valoración prequirúrgica propiamente dicha. Arriba de todo hay una tarjeta de <b>atajos</b> —ver «La valoración exprés», más abajo—, después la <b>historia del paciente de lectura</b> y debajo los once puntos completos, que se despliegan uno debajo del otro:"}, {"t": "aviso", "clase": "info", "tit": "<b>Los antecedentes ya no se cargan acá</b>", "cuerpo": ["Hasta la versión anterior, los cinco primeros puntos de la valoración —antecedentes patológicos, revisión por sistemas, antecedentes anestésicos y familiares, medicación habitual, alergias y hábitos— preguntaban <b>exactamente lo mismo</b> que las cuatro solapas de «anotar nuevo paciente». Era el mismo formulario dos veces: se cargaba en un lado, se corregía en el otro, y después había dos versiones del mismo antecedente sin forma de saber cuál valía.", "Ahora se carga <b>una sola vez</b>, en la historia del paciente, que es su lugar: los antecedentes son de la persona, no de esta cirugía. La valoración los <b>muestra</b> en una tarjeta de lectura, arriba de todo, con un botón que lleva a la historia para corregirlos.", "Lo que sí es de esta cirugía —qué hacer con cada fármaco antes de operar— se quedó en la valoración y pasó a ser el <b>punto 1</b>, que ahora se calcula solo."]}, {"t": "li", "num": false, "txt": "<b>1</b> — <b>conducta perioperatoria de la medicación habitual</b>. Es el punto nuevo y no se completa: se calcula. Ver «La conducta perioperatoria se arma sola», más abajo."}, {"t": "li", "num": false, "txt": "<b>2 a 6</b> — examen físico y semiología, vía aérea, laboratorio y estudios complementarios, estratificación del riesgo —las cinco escalas, más capacidad funcional y fragilidad— y ayuno preoperatorio."}, {"t": "li", "num": false, "txt": "<b>7</b> — conclusión de aptitud: apto, apto con reservas, requiere optimización o no apto, con su fundamentación e interconsultas."}, {"t": "li", "num": false, "txt": "<b>8</b> — plan anestésico: técnica, vía aérea, monitoreo estándar y avanzado, accesos."}, {"t": "li", "num": false, "txt": "<b>9</b> — profilaxis antibiótica, tromboprofilaxis, profilaxis de náuseas y vómitos, destino postoperatorio previsto y previsión transfusional. <b>La analgesia postoperatoria ya no está acá</b>: se indica en el paso <b>Recuperación</b>, después del destino. Ver más abajo."}, {"t": "li", "num": false, "txt": "<b>10</b> — anestesiólogo designado para realizar el acto."}, {"t": "li", "num": false, "txt": "<b>11</b> — consentimiento informado anestésico."}, {"t": "h3", "txt": "La precarga abierta: el paciente que se anota solo"}, {"t": "p", "txt": "Además del botón de arriba —que es <b>por invitación</b>: vos emitís el enlace para un paciente que ya tenés cargado— hay una <b>puerta abierta</b> para el que todavía no existe en la aplicación. La persona que sacó turno para una consulta prequirúrgica entra sola a <b>'</b>, deja sus datos y aparece en tu bandeja."}, {"t": "p", "txt": "No hace falta que crees nada ni que sepas que existe: el paciente llega primero."}, {"t": "h3", "txt": "Cómo entra el paciente"}, {"t": "li", "num": true, "txt": "Pone su <b>DNI y su correo</b>. Nada más: no hay cuenta ni contraseña que recordar."}, {"t": "li", "num": true, "txt": "Le llega un <b>enlace personal</b> por mail. Ese enlace es la verificación: sólo llega a su casilla, así que si lo abrió es porque el correo es suyo."}, {"t": "li", "num": true, "txt": "Completa <b>tres pantallas</b>: sus datos, su salud —las mismas preguntas del portal por invitación— y <b>su turno</b>: institución, día, hora y una <b>foto del ticket</b>."}, {"t": "li", "num": true, "txt": "Toca FINALIZADO y aparece en la bandeja. Puede volver con el mismo enlace y corregir, hasta que un anestesiólogo lo tome."}, {"t": "aviso", "clase": "info", "tit": "<b>Por qué un enlace y no un código de seis dígitos</b>", "cuerpo": ["Un código que genera el navegador del propio paciente y que después ese mismo navegador verifica no prueba nada: se saltea sin esfuerzo. El enlace sí prueba, porque el único camino para llegar a él es la casilla de correo.", "Y de paso evita el costo escondido de las cuentas: contraseñas olvidadas, recuperación, y una línea de soporte que la asociación no tiene, para un formulario que se llena una vez."]}, {"t": "h3", "txt": "La bandeja: Pacientes → Precargados"}, {"t": "p", "txt": "En <b>Pacientes</b> hay una tercera solapa, <b>Precargados</b>, con el número de los que están esperando. <b>No es una lista alfabética: es una agenda</b>, agrupada por institución y por día. El que atiende los martes en el HRU abre y ve su martes."}, {"t": "p", "txt": "Cada renglón trae la hora, el apellido, el documento y dos sellos que conviene mirar:"}, {"t": "li", "num": false, "txt": "<b>Ticket</b> en verde, o <b>Sin ticket</b> en amarillo. El comprobante del turno es la prueba de que el turno existe: es la diferencia entre una precarga confiable y una declaración sin respaldo."}, {"t": "li", "num": false, "txt": "<b>En el padrón</b>, si ya hay un paciente con ese DNI. Al tomarlo se <b>suma a esa historia</b>, no se crea uno nuevo."}, {"t": "p", "txt": "Un día que ya pasó y que nadie tomó se marca en rojo con <i>«sin tomar»</i>: es una deuda visible, no un renglón más."}, {"t": "aviso", "clase": "warn", "tit": "<b>Es una declaración, no un turno confirmado</b>", "cuerpo": ["El paciente dice que viene el martes. La institución no validó nada y el turno se puede mover. La bandeja te sirve para prepararte, no para saber con certeza quién viene: no la trates como el parte del día.", "Y como cualquier puerta abierta a internet, puede entrar basura. Por eso importa el ticket: una precarga sin comprobante merece una llamada antes de preparar nada."]}, {"t": "h3", "txt": "Tomar un paciente precargado"}, {"t": "p", "txt": "Al tocar un renglón se abre todo lo que cargó, con la foto del ticket. El botón <b>Tomar este paciente</b> hace tres cosas, en este orden:"}, {"t": "li", "num": true, "txt": "Resuelve <b>quién es</b>: si ya está en el padrón con ese DNI, se suma a su historia; si no, se crea."}, {"t": "li", "num": true, "txt": "Abre la <b>misma revisión campo por campo</b> del portal por invitación: lo que escribió el paciente no entra solo, vos tildás qué incorporás."}, {"t": "li", "num": true, "txt": "Te ofrece <b>abrir su ficha</b> con la institución ya propuesta, y sigue el recorrido normal de siempre."}, {"t": "p", "txt": "La medicación que incorpores entra con su <b>conducta perioperatoria ya calculada</b> desde el vademécum, marcada como <i>referida por el paciente</i>. Es decir: llega a la consulta con el punto 1 de la valoración medio hecho."}, {"t": "aviso", "clase": "info", "tit": "<b>Qué hace falta para que esto funcione</b>", "cuerpo": ["El envío de mails configurado, la base compartida en línea, y las reglas de la rama <b>afar-precargas</b> pegadas en la consola de Firebase (ver reglas-firebase.txt).", "Y algo que no es de la aplicación y es lo que decide si se usa o no: <b>que los pacientes se enteren de la dirección</b>. Un QR en el ticket del turno, un cartel en admisión, que lo diga la secretaria. Sin eso la función existe y no la usa nadie."]}, {"t": "p", "txt": "Las precargas que nadie toma se borran solas a los 15 días del turno declarado: una ficha sin profesional responsable no puede quedar dando vueltas en la base."}, {"t": "aviso", "clase": "info", "tit": "<b>Al paciente precargado no se le vuelve a pedir la ficha</b>", "cuerpo": ["Cuando la ficha nace de una precarga, el botón <b>Enviarle la ficha por mail</b> del paso Paciente <b>no aparece</b>. Es a propósito: ese botón sirve para pedirle al paciente los datos que no tenemos, y de un precargado los tenemos todos. Mandarle el mail sería pedirle que complete por segunda vez exactamente lo mismo que ya completó en su casa.", "En su lugar queda un cartel que dice de dónde salieron esos datos: el día y la institución que declaró, y si adjuntó o no la foto del ticket.", "La marca es de <b>esa ficha</b>, no del paciente. Si el año que viene la misma persona se opera de otra cosa, esa ficha nueva no la tiene y el botón vuelve a aparecer — que es lo correcto, porque la precarga vieja no dice nada de la intervención nueva."]}, {"t": "h2", "txt": "Paso 2 · Preanestesia"}, {"t": "h3", "txt": "La conducta perioperatoria se arma sola"}, {"t": "p", "txt": "El punto 1 es el único de los once que no se completa: se <b>calcula</b>. Toma la medicación cargada en la historia del paciente, la cruza con el vademécum perioperatorio —137 fármacos con los días de anticipación, las horas que pide ASRA para el neuroeje y las alertas que no se pueden pasar por alto— y devuelve la conducta ya resuelta."}, {"t": "p", "txt": "Arriba de todo hay un campo opcional, <b>fecha prevista de la cirugía</b>. Si se carga, la conducta deja de expresarse en días y pasa a decir fechas: <i>«Semaglutida — sin tomarla desde el 8 de octubre»</i>. No es la fecha del acto, que se carga el día de la cirugía en el paso Anestesia: sirve sólo para armar el calendario que se le entrega al paciente."}, {"t": "p", "txt": "Debajo, la conducta repartida en cuatro cajones, cada uno con su color:"}, {"t": "li", "num": false, "txt": "<b>Suspender antes de la cirugía</b>, con la fecha desde la cual no lo toma más y cuándo se reanuda."}, {"t": "li", "num": false, "txt": "<b>Omitir sólo la dosis de la mañana</b> —los IECA, los diuréticos—."}, {"t": "li", "num": false, "txt": "<b>Continuar, incluida la mañana</b>, con un sorbo de agua: los betabloqueantes, los anticonvulsivantes, las estatinas."}, {"t": "li", "num": false, "txt": "<b>A definir por el anestesiólogo</b>: la aspirina, el litio, los inmunosupresores."}, {"t": "aviso", "clase": "danger", "tit": "<b>Lo que no se puede pasar por alto</b>", "cuerpo": ["Arriba de los cuatro cajones, en rojo, van las alertas del vademécum. Son las que suspenden cirugías cuando nadie las vio: la <b>semaglutida</b> que deja el estómago lleno con el ayuno cumplido, el <b>iSGLT2</b> que hace cetoacidosis con la glucemia normal, el <b>betabloqueante</b> que no se suspende nunca, el <b>clopidogrel</b> que no se suspende sin hablar con cardiología si hay stent reciente.", "Y si el plan incluye una técnica <b>neuroaxial</b> o un bloqueo profundo, aparece un bloque aparte con las esperas mínimas de ASRA desde la última dosis. Si la espera no se puede cumplir, la indicación es cambiar de técnica, no acortarla."]}, {"t": "p", "txt": "El botón <b>Pasar a las indicaciones del paciente</b> convierte todo eso a castellano llano y lo escribe en el punto 9, que es lo que después sale impreso en la hoja que el paciente se lleva."}, {"t": "aviso", "clase": "warn", "tit": "<b>La app calcula, el anestesiólogo confirma</b>", "cuerpo": ["Es la misma regla del vademécum anestésico y por el mismo motivo. Ninguna conducta se aplica sola y todas son editables: la de cada fármaco se cambia en la historia del paciente, en la solapa <b>Medicación</b>. Lo que se ve en el panel es lo que dicen las guías, con las fechas ya hechas; la decisión sigue siendo de la persona que firma."]}, {"t": "h3", "txt": "La valoración exprés: los atajos de arriba"}, {"t": "p", "txt": "La valoración tiene once puntos porque la historia clínica los pide. Pero para <b>concluirla</b> y que sostenga un acto anestésico hacen falta seis cosas, no once: peso, ASA, vía aérea, conclusión de aptitud fundamentada, plan y consentimiento. La tarjeta de arriba muestra esas seis con su estado a la vista y un botón <b>Ir</b> al lado de cada una que falta, que abre el punto exacto y lo deja centrado en la pantalla. Los once puntos siguen abajo, enteros: no se sacó nada."}, {"t": "p", "txt": "En esa misma tarjeta hay dos botones que son los que de verdad ahorran tiempo."}, {"t": "h3", "txt": "Autocompletar con lo cargado"}, {"t": "p", "txt": "El punto 5 tenía <b>más de cincuenta casillas</b> siempre a la vista, y casi todas preguntan algo que ya está escrito dos pantallas antes. El RCRI pregunta cardiopatía isquémica, insuficiencia cardíaca, ACV, diabetes con insulina y creatinina mayor de 2: las cinco están en los puntos 1, 3 y 8. El STOP-BANG pregunta IMC, edad, circunferencia del cuello y sexo. El Apfel pregunta sexo, si fuma y si va a llevar opioides. El ARISCAT pregunta edad, SpO₂, anemia, tipo de incisión y si es urgencia."}, {"t": "p", "txt": "El botón <b>Autocompletar con lo cargado</b> deriva todo eso y abre una ventana con lo que va a marcar y <b>por qué</b>, renglón por renglón: «IMC 36,3 calculado con el peso y la talla», «la cirugía es laparoscópica: entra en el criterio de alto riesgo del índice de Lee», «Apfel 2 de 4: corresponde profilaxis doble». Cada renglón se puede destildar. También propone la <b>profilaxis de náuseas y vómitos</b> según el Apfel y la <b>tromboprofilaxis</b> según el Caprini, y marca los riesgos de aspiración del punto 10 que se deducen: urgencia, agonista GLP-1 sin suspender, reflujo, embarazo, obesidad mórbida."}, {"t": "aviso", "clase": "ok", "tit": "<b>No inventa y no pisa</b>", "cuerpo": ["El autocompletado no crea ningún dato clínico: sólo deriva de lo que ya está escrito, y cada renglón dice de dónde sale. Lo que el anestesiólogo cargó a mano no se toca. Si algo deducido <b>contradice</b> lo cargado —la incisión declarada dice «periférica» y la vía del paso 1 es laparoscópica— la propuesta aparece igual pero <b>destildada</b>, con la leyenda «reemplaza «periférica»», para que la resuelva la persona."]}, {"t": "p", "txt": "Lo que <b>no</b> se deduce, a propósito: el ronquido, la somnolencia y las apneas observadas del STOP-BANG sólo se marcan si hay apnea del sueño diagnosticada en el punto 1, porque son síntomas que se preguntan, no que se calculan. Y la <b>aptitud</b> del punto 11 no se deduce nunca: la firma una persona."}, {"t": "h3", "txt": "El ASA propuesto"}, {"t": "p", "txt": "Mientras el ASA esté vacío, la tarjeta muestra el que corresponde según los antecedentes, el IMC, la capacidad funcional en MET y el laboratorio, con su fundamento escrito: «ASA propuesto: III. Por obesidad (IMC 36,3), capacidad funcional menor de 4 MET». Se acepta con un clic y se puede cambiar en el punto 5. Si da III o más, la aplicación avisa que el ASA III se apoya en el <b>grado de control</b> de cada enfermedad y no sólo en su presencia, y que hay que revisarlo antes de aceptarlo. Se propone; no se aplica solo: de él dependen el adicional del honorario y la lectura que hace después cualquiera que abra la historia."}, {"t": "h3", "txt": "Las plantillas"}, {"t": "p", "txt": "El botón <b>Usar una plantilla</b> ofrece cuatro situaciones, que son la enorme mayoría de las valoraciones: <b>paciente sano para cirugía menor</b>, <b>adulto con HTA o diabetes compensadas</b>, <b>urgencia con estómago ocupado</b> y <b>pediátrico sano</b>. Cada una rellena de una vez el examen físico normal redactado, la vía aérea sin hallazgos, el ayuno, la técnica, el manejo de la vía aérea, la analgesia postoperatoria, la profilaxis de NVPO, la tromboprofilaxis, el destino y el ámbito. No pisa nada de lo que ya esté cargado y todo queda editable."}, {"t": "aviso", "clase": "warn", "tit": "<b>Una plantilla es un punto de partida, no una valoración</b>", "cuerpo": ["La aplicación lo dice en la propia ventana antes de aplicarla. Lo que rellena es la redacción habitual de esa situación para no tener que tipearla: hay que leerla y corregir lo que no coincida con este paciente antes de guardar. Lo que se firma después es historia clínica."]}, {"t": "h3", "txt": "La conclusión redactada sola"}, {"t": "p", "txt": "El punto 11 tiene un botón <b>Redactar con lo cargado</b>. Es el campo que más tiempo llevaba y el único enteramente derivable: la fundamentación es el resumen de lo que ya está arriba. Arma un texto con la edad, el sexo, el IMC, los procedimientos y el diagnóstico, los antecedentes, la medicación con lo que hay que suspender, el ASA, los MET, el Mallampati y el El-Ganzouri, las cinco escalas con su número y su nivel, el laboratorio con lo que está fuera de rango, el ayuno, el plan, la analgesia, la tromboprofilaxis, las medidas de mitigación que se desprenden de los dominios en riesgo alto, y la aptitud elegida. Queda <b>editable</b>, y si ya había texto escrito no lo pisa: pregunta si agregarlo debajo."}, {"t": "h3", "txt": "El punto 5, más corto"}, {"t": "p", "txt": "Las cinco escalas muestran ahora el <b>resultado arriba</b> —el número, el nivel de riesgo y la conducta que corresponde— y esconden sus ítems detrás de un desplegable <b>«Revisar los N ítems»</b>. Se abren cuando hay que corregir alguno. De cincuenta y tres casillas siempre a la vista se pasó a cinco tarjetas de resultado."}, {"t": "h3", "txt": "Las escalas se calculan solas"}, {"t": "p", "txt": "A medida que se completa, la aplicación calcula: ASA, El-Ganzouri (vía aérea difícil), RCRI (riesgo cardíaco), STOP-BANG (apnea del sueño), Apfel (náuseas y vómitos), Caprini (riesgo tromboembólico), ARISCAT (complicaciones respiratorias) e IMC. No hay que buscar tablas ni calcular a mano."}, {"t": "h3", "txt": "El punto 11 es obligatorio"}, {"t": "p", "txt": "Sin el consentimiento informado completo no se puede concluir la valoración. Es un requisito de la Ley 26.529 para todo procedimiento con riesgo relevante, y la anestesia lo es."}, {"t": "p", "txt": "El texto tiene once apartados: naturaleza del acto anestésico, técnicas y en qué consisten, monitoreo, riesgos frecuentes, poco frecuentes y graves, instrucciones de ayuno y medicación, situaciones imprevistas, transfusión, declaración jurada de antecedentes, revocación y datos personales. Está redactado sobre el modelo de la Asociación de Anestesia, Analgesia y Reanimación de Buenos Aires y los formularios del Ministerio de Salud de la Nación."}, {"t": "p", "txt": "Se firma con el lápiz o dedo en la tablet, con el mouse en la computadora o con el lápiz o dedo en el teléfono, sobre el mismo lienzo. El anestesiólogo además puede traer la firma que tiene guardada en su perfil o subir una imagen."}, {"t": "p", "txt": "Las dos únicas salidas legítimas sin firma son la <b>urgencia vital</b> (art. 9 de la Ley 26.529) y la <b>revocación del paciente</b>. Las dos se eligen en el mismo desplegable y quedan asentadas, que es exactamente lo que la ley manda hacer con ellas."}, {"t": "img", "src": "manual/m5.jpg"}, {"t": "h3", "txt": "Al guardar la valoración se habilita la documentación"}, {"t": "p", "txt": "Recién al tocar <b>Guardar valoración</b> se encienden los cuatro botones del pie: <b>Honorarios de la consulta</b>, Word, PDF y Enviar valoración al paciente. Antes están apagados a propósito: un PDF de una valoración a medio cargar no le sirve a nadie, y mandárselo así al paciente es peor."}, {"t": "p", "txt": "<b>Word y PDF bajan sólo la valoración</b>: los datos del paciente y los once puntos con su consentimiento, <b>sin el registro del acto</b> —que el día de la consulta todavía no existe, y que además puede ser de un colega—. Es el documento de ese día y se archiva por separado."}, {"t": "p", "txt": "Y el botón de honorarios abre <b>únicamente el de la consulta prequirúrgica</b>. Antes abría la ventana entera, con las unidades anestésicas del acto a la vista: un dato que en ese momento nadie tiene. El honorario del acto se carga al firmar, en el paso 5."}, {"t": "h3", "txt": "Cada paso abre lo suyo"}, {"t": "p", "txt": "Una ficha tiene dos secciones —la valoración y el acto— y la pantalla enfoca una por vez. Entrar a un paso <b>pone su sección en foco solo</b>: si se viene del acto y se abre la Preanestesia, la valoración queda lista para trabajar sin ningún paso intermedio."}, {"t": "p", "txt": "Lo que no cambia es de quién es cada cosa. Si la valoración es de un colega, se ve completa pero en <b>sólo lectura</b>, con el cartel del candado. Eso lo decide la titularidad, no el foco."}, {"t": "aviso", "clase": "info", "tit": "<b>Por eso «Guardar valoración» aparece y desaparece</b>", "cuerpo": ["El botón sólo se dibuja cuando esa sección es tuya. Un botón de guardar sobre algo que no se puede tocar es un botón muerto en el medio de la pantalla. Y no se pasó a autoguardado a propósito: <b>«Guardar valoración» no es sólo guardar, es concluirla</b> —es lo que enciende los cuatro botones de documentación y lo que fija la fecha—. Igual no se pierde nada: al tocar «Siguiente» se graba todo antes de cambiar de paso."]}, {"t": "h3", "txt": "Qué recibe el paciente"}, {"t": "p", "txt": "Un correo de la AFAAR con tres archivos PDF separados:"}, {"t": "li", "num": false, "txt": "<b>Valoración </b><b>pre-anestésica</b> — filiación, antecedentes, medicación, alergias, examen, laboratorio, escalas y plan."}, {"t": "li", "num": false, "txt": "<b>Consentimiento informado anestésico</b> — el texto completo, las declaraciones que marcó y las dos firmas. Va aparte porque es un instrumento jurídico autónomo."}, {"t": "li", "num": false, "txt": "<b>Indicaciones para el día de la cirugía</b> — en castellano llano: ayuno, qué medicación seguir tomando y cuál suspender, qué llevar, con quién venir y en qué casos avisar antes."}, {"t": "p", "txt": "Los tres llevan el membrete de la institución, los datos y matrículas del profesional y el pie legal. No sale un solo dato de facturación. Las respuestas del paciente le llegan al anestesiólogo, no a la casilla de la asociación."}, {"t": "h2", "txt": "Paso 3 · Anestesia"}, {"t": "p", "txt": "El registro intraoperatorio. Lo primero que aparece, imposible de pasar por alto, es el botón <b>TOMAR ACTO ANESTÉSICO</b>."}, {"t": "aviso", "clase": "info", "tit": "<b>Por qué el acto se toma y no se asigna</b>", "cuerpo": ["Un acto anestésico tiene que tener un dueño con nombre y apellido antes de que se escriba una sola línea. Es quien firma, quien responde y a nombre de quien se factura. En el punto 10 se designa a alguien, pero una designación no es una toma: el designado puede no estar, y en una urgencia anestesia el que está."]}, {"t": "img", "src": "manual/m6.jpg"}, {"t": "p", "txt": "Una vez tomado, hay cinco solapas:"}, {"t": "li", "num": false, "txt": "<b>Resumen</b> — fecha real de la cirugía, <b>carácter del acto</b>, cronómetro de los seis tiempos (ingreso, inicio de anestesia, inicio de cirugía, fin de cirugía, fin de anestesia, salida), técnica, vía aérea con Cormack e intentos, monitorización, equipo quirúrgico y lista de verificación de la OMS."}, {"t": "li", "num": false, "txt": "<b>Drogas</b> — con el vademécum anestésico AFAAR de adultos y pediatría, 64 fármacos en 13 grupos. Calcula por peso y muestra el rango, pero nunca registra una dosis sola: propone el punto medio, queda editable y hay que confirmarla."}, {"t": "li", "num": false, "txt": "<b>Signos vitales</b> — controles seriados con gráfico y alertas de inestabilidad, y un <b>preseteado de valores normales</b> calculado para ese paciente. Debajo de cada sigla aparece en letra chica lo que significa. Ver más abajo."}, {"t": "li", "num": false, "txt": "<b>Balance</b> — cristaloides, coloides, hemoderivados, diuresis y sangrado, con balance calculado, y arriba un <b>plan de fluidos propuesto</b> para este paciente y esta cirugía. Ver más abajo."}, {"t": "li", "num": false, "txt": "<b>Eventos</b> — 25 tipos de evento intraoperatorio tipificados, con los <b>más probables en este paciente</b> ordenados arriba. Ver más abajo."}, {"t": "aviso", "clase": "ok", "tit": "<b>No hay botón Guardar, y es deliberado</b>", "cuerpo": ["Las cinco solapas se guardan solas a medida que se editan. El acto se registra mientras se anestesia, con una mano, entre dos drogas y mirando el monitor. Pedirle a esa persona que se acuerde de guardar es pedirle lo único que seguro se va a olvidar, y lo que se pierde es el registro de un acto médico."]}, {"t": "h3", "txt": "El control horario sin novedad"}, {"t": "p", "txt": "El registro intraoperatorio pide un control por hora. En un acto sin novedad eso son siete números por hora escritos a mano con guantes puestos, y es la razón por la que la solapa quedaba vacía: nadie lo hace."}, {"t": "p", "txt": "Ahora, arriba del botón azul, hay un <b>preseteado de valores normales calculado para ese paciente</b> a partir de su edad, sexo, peso, talla e IMC, y dos botones: <b>Control normal — HH:MM</b>, que carga el control de esta hora de un toque, y <b>Completar N horas pendientes</b>, que llena de una vez todas las horas en punto que falten entre el inicio y el fin de la anestesia. El botón azul <b>Registrar control</b> sigue estando y es el que hay que usar en cuanto algo se sale de lo normal."}, {"t": "p", "txt": "Las franjas etarias son <b>siete</b>, no las seis de uso coloquial, porque «pediátrico» reúne edades que no se parecen en nada: un recién nacido tiene una frecuencia cardíaca de 140 y un chico de diez años, de 85. Meterlos en la misma franja haría que el preseteado fuera falso justo donde más importa. La división es la de PALS/APLS, que es la que se usa en la práctica:"}, {"t": "tabla", "head": ["Franja", "Edad", "TA", "FC", "FR", "SpO₂", "EtCO₂", "Temp"], "rows": [["<b>Neonato</b>", "0 a 28 días", "65/40", "135", "40", "97 %", "34", "36,8 °C"], ["<b>Lactante</b>", "29 días a 12 meses", "85/50", "125", "30", "98 %", "34", "36,8 °C"], ["<b>Preescolar</b>", "1 a 5 años", "95/55", "105", "24", "98 %", "35", "36,6 °C"], ["<b>Escolar</b>", "6 a 11 años", "105/62", "88", "20", "98 %", "35", "36,5 °C"], ["<b>Adolescente</b>", "12 a 17 años", "112/66", "78", "16", "98 %", "35", "36,5 °C"], ["<b>Adulto</b>", "18 a 64 años", "115/70", "70", "14", "98 %", "35", "36,3 °C"], ["<b>Adulto mayor</b>", "65 años en adelante", "125/72", "68", "15", "96 %", "35", "36,2 °C"]]}, {"t": "p", "txt": "«Joven» y «adulto» se unificaron: entre los 20 y los 60 años los valores normales no cambian, y una franja que no cambia nada es una franja que sólo agrega un clic."}, {"t": "p", "txt": "Los valores son los <b>esperables bajo anestesia</b>, no los de la sala de espera: con el paciente dormido la tensión y la frecuencia bajan entre un 10 y un 20 %, y ése es el número que corresponde asentar en el registro del acto. Sobre la franja se aplican después los ajustes del paciente concreto, que la aplicación muestra escritos: IMC ≥ 30 sube la tensión 8/5 mmHg; IMC ≥ 40 la sube 10/6 y baja la SpO₂ a 96 %; el sexo masculino suma 3 mmHg de sistólica en adultos; la talla por encima de 185 cm suma 4 y por debajo de 155 cm resta 4; y en menores de 12 años el peso corrige la frecuencia cardíaca contra lo esperado para la edad."}, {"t": "p", "txt": "El botón <b>Ajustar estos valores</b> permite cambiar el preseteado para esa ficha —queda dicho en pantalla que se están usando valores ajustados a mano—, y <b>Volver al calculado</b> lo devuelve."}, {"t": "aviso", "clase": "warn", "tit": "<b>Es un atajo para escribir, no un relleno</b>", "cuerpo": ["Los controles cargados así quedan marcados <b>NORMAL</b> en la tabla y en el registro impreso, y el botón de completar horas pide confirmación antes de cargar. Un registro de signos vitales es historia clínica: el preseteado sirve para escribir más rápido lo que el anestesiólogo <b>está viendo en el monitor</b>, no para rellenar horas que no se miraron."]}, {"t": "h3", "txt": "El gráfico: todos los parámetros, cada uno en su escala"}, {"t": "p", "txt": "El botón <b>Ver gráfico</b> dibujaba cuatro curvas —TA sistólica, TA diastólica, FC y SpO₂— apiladas sobre una única escala de 0 a 200. Con esa escala la saturación quedaba aplastada contra el techo y no se la veía moverse, y el EtCO₂ y la temperatura directamente no se dibujaban: 35 y 36 sobre 200 caen los dos en el mismo renglón de abajo. La frecuencia respiratoria y el TOF ni siquiera estaban."}, {"t": "p", "txt": "Ahora se dibuja <b>todo lo que se haya cargado</b>, en franjas apiladas que comparten el eje de tiempo, y <b>cada parámetro tiene su propia escala</b>: presión arterial, frecuencia cardíaca, saturación, EtCO₂, frecuencia respiratoria, temperatura y TOF. En cada franja está escrito el rango a la izquierda, la <b>banda de normalidad sombreada</b> con sus límites a la derecha, y los puntos que caen fuera de ese rango se pintan en rojo y se agrandan. Sólo se dibujan las franjas que tienen datos: una ficha sin temperatura no muestra una franja vacía."}, {"t": "p", "txt": "La primera franja es la hemodinamia junta, como en la hoja de anestesia de siempre: la sistólica arriba, la diastólica abajo, unidas por su barra vertical, y la <b>presión arterial media</b> punteada en el medio. La media no se carga: se calcula sola como (sistólica + 2 × diastólica) / 3, aparece como columna propia en la tabla y en el registro impreso, y tiene su propia alerta por debajo de 65 mmHg. Es la que gobierna la perfusión de órgano, y una 95/45 da una media de 62 sin que ninguno de los dos números parezca alarmante por separado."}, {"t": "h3", "txt": "El TOF, ahora medido en vez de escrito"}, {"t": "p", "txt": "<b>TOF</b> es el tren de cuatro (<i>train-of-four</i>): el monitoreo de la relajación neuromuscular. Se aplican <b>cuatro estímulos supramaximales a 2 Hz</b> —uno cada medio segundo, dos segundos en total— sobre un nervio periférico y se observa la respuesta del músculo que inerva. El sitio habitual es el <b>nervio cubital en la muñeca</b> con la respuesta del aductor del pulgar; cuando el brazo no está accesible se usan el facial (orbicular del ojo o corrugador superciliar) o el tibial posterior (flexor del hallux), que no son equivalentes entre sí y por eso el sitio ahora se registra."}, {"t": "p", "txt": "El resultado se lee de <b>dos maneras distintas, que no son lo mismo</b>, y hasta ahora la aplicación las mezclaba en un único campo de texto libre donde «4» podía querer decir cuatro respuestas o cuatro por ciento. Ahora se piden por separado:"}, {"t": "tabla", "head": ["Medida", "Qué es", "Qué hace falta para medirla", "Para qué sirve"], "rows": [["<b>Recuento</b> (0 a 4)", "Cuántas de las cuatro respuestas se ven o se palpan", "Cualquier estimulador de nervio periférico", "Graduar la profundidad del bloqueo durante la cirugía y decidir la dosis de reversión"], ["<b>Cociente T4/T1</b> (%)", "Cuánto vale la cuarta respuesta respecto de la primera", "Monitoreo <b>cuantitativo</b>: aceleromiografía, electromiografía o kinemiografía", "Es el <b>único</b> que descarta bloqueo residual y habilita la extubación"]]}, {"t": "p", "txt": "La lectura de la profundidad, de más profundo a más superficial: recuento <b>0</b>, bloqueo profundo —para valorarlo hace falta el recuento post-tetánico—; recuento <b>1 a 3</b>, bloqueo quirúrgico; recuento <b>4</b>, bloqueo superficial. Y después, la parte que decide: el <b>desvanecimiento entre la primera y la cuarta respuesta deja de verse a simple vista por encima de un cociente de 0,4</b>. Es decir que un paciente con las cuatro respuestas visibles y sin desvanecimiento aparente puede tener todavía un cociente de 0,4 y estar con debilidad faríngea, riesgo de aspiración y obstrucción de la vía aérea superior. Por eso el umbral aceptado para extubar es <b>cociente ≥ 90 %</b>, y sólo se puede afirmar midiéndolo."}, {"t": "p", "txt": "La aplicación aplica esa lectura sola. Al cargar el control avisa según lo que se anote: cociente por debajo de 90 % es aviso rojo de bloqueo residual con la indicación de revertir y volver a medir; por encima, aviso verde de recuperación adecuada; recuento 0 recuerda que la neostigmina no revierte a esa profundidad y que el sugammadex requiere 4 mg/kg; y recuento 4 sin cociente cargado avisa que cuatro respuestas visibles no son sinónimo de recuperación. Un TOF menor de 90 % en cualquier control entra además en el resumen de «Para revisar» de la solapa y del gráfico."}, {"t": "p", "txt": "En el gráfico, el <b>cociente</b> se dibuja como círculo lleno en su valor real y el <b>recuento</b> como cuadrado hueco, llevado a la misma escala a razón de 25 % por respuesta, con el valor literal escrito al lado de cada punto. Se dibujan distinto justamente para que no se confundan."}, {"t": "h3", "txt": "Qué quiere decir cada sigla"}, {"t": "p", "txt": "Las abreviaturas de signos vitales son transparentes para el anestesiólogo y opacas para todos los demás, y la ficha la leen además el paciente, la auditoría del financiador, el cirujano y el residente que recién empieza. Ahora <b>debajo de cada sigla, en letra chica, dice lo que significa</b>: en las tarjetas del último control y en la cabecera de la tabla de controles."}, {"t": "tabla", "head": ["Sigla", "Qué es"], "rows": [["<b>TA</b>", "presión arterial"], ["<b>PAM</b>", "presión arterial media"], ["<b>FC</b>", "frecuencia cardíaca"], ["<b>FR</b>", "frecuencia respiratoria"], ["<b>SpO₂</b>", "saturación de oxígeno"], ["<b>EtCO₂</b>", "CO₂ espirado final"], ["<b>Temp</b>", "temperatura"], ["<b>TOF</b>", "tren de cuatro"]]}, {"t": "p", "txt": "Lo mismo pasó con <b>URPA</b> en el paso 4: la sigla se usa cinco veces y sale impresa en el registro, así que arriba de la tarjeta se aclara una vez que es la <b>Unidad de Recuperación Post-Anestésica</b>."}, {"t": "h3", "txt": "El plan de fluidos propuesto"}, {"t": "p", "txt": "La solapa <b>Balance</b> era una lista de campos vacíos. La cuenta que hay que hacer para llenarlos —mantenimiento, déficit de ayuno, pérdidas por trauma quirúrgico— se hacía de cabeza, con guantes puestos, o no se hacía."}, {"t": "p", "txt": "Ahora arriba de los campos hay un <b>plan calculado con lo que la ficha ya tiene cargado</b>: sexo, peso, talla, IMC, edad, antecedentes, medicación y la cirugía prevista con su vía de abordaje. Se despliega renglón por renglón, con el fundamento de cada uno:"}, {"t": "tabla", "head": ["Renglón", "De dónde sale"], "rows": [["<b>Peso de cálculo</b>", "El peso real, salvo con IMC ≥ 30: ahí usa el <b>peso ajustado</b> (ideal de Devine más el 40 % del exceso). En el obeso el agua corporal no crece como el peso, y con el peso real la reposición sale casi al doble"], ["<b>Mantenimiento</b>", "Regla 4-2-1 de Holliday-Segar, por la duración prevista"], ["<b>Duración</b>", "La real si ya están cargados los horarios del acto; si no, la estimada por la complejidad del nomenclador, y se recalcula sola al cargarlos"], ["<b>Trauma quirúrgico</b>", "Mínimo 2, moderado 4 o severo 6 mL/kg/h, según la <b>vía de abordaje</b> declarada en el paso 1. Más de dos procedimientos en el mismo acto suben un grado"], ["<b>Ayuno</b>", "Horas desde la última ingesta del punto 10. Si no está cargada, asume 8 h y lo dice. Se propone reponer la mitad del déficit"], ["<b>Corrección restrictiva</b>", "Baja el total con insuficiencia cardíaca, enfermedad renal o diálisis, y explica por qué"]]}, {"t": "p", "txt": "Al lado quedan tres cifras que son las que se miran de verdad durante el acto: la <b>diuresis esperable</b> (0,5 mL/kg/h en el adulto, 1 en el chico), la <b>volemia estimada</b> (70 mL/kg, 80 en pediatría) y la <b>pérdida sanguínea admisible</b>, calculada desde el hematocrito del punto 8 hasta el umbral de transfusión —27 % si hay cardiopatía o insuficiencia cardíaca, 24 % si no—."}, {"t": "p", "txt": "Debajo aparecen las advertencias que correspondan: insuficiencia cardíaca, diálisis, enfermedad renal, hepatopatía, cardiopatía isquémica, embarazo, obesidad mórbida, paciente pediátrico, anemia previa, rechazo de hemoderivados, diurético habitual o iSGLT2 sin suspender. Cada una dice qué cambia en la conducta, no sólo que existe."}, {"t": "aviso", "clase": "warn", "tit": "<b>Es un techo, no una meta</b>", "cuerpo": ["La cifra clásica del tercer espacio (2 · 4 · 6 mL/kg/h) sobreestima la reposición según las guías de recuperación acelerada (ERAS), que trabajan con esquemas restrictivos y guiados por objetivos. El plan lo dice en pantalla, al pie del cálculo."]}, {"t": "p", "txt": "El botón <b>Volcar al balance</b> escribe los cristaloides y la diuresis esperable en los campos de abajo, que <b>siguen siendo editables</b> como cualquier otro número. <b>No pisa nada que ya tenga un valor cargado</b>: si hay cristaloides escritos, ese número lo vio pasar por la vía una persona. Sin peso cargado no hay plan, y lo dice: sin peso eso no sería una estimación sino un número inventado."}, {"t": "h3", "txt": "Los eventos más probables"}, {"t": "p", "txt": "El desplegable de tipos de evento tiene veinticinco entradas, todas iguales, en orden alfabético de nadie. Cuando el evento está pasando —el paciente desaturando y una mano libre— buscar «Broncoespasmo» entre veinticinco es tiempo que no hay."}, {"t": "p", "txt": "Arriba de la solapa <b>Eventos</b> aparecen ahora los cinco a ocho que este paciente y esta cirugía hacen probables, <b>cada uno con el motivo por el que subió</b>: el asma del punto 1, el SAHOS, el IMC, la anticoagulación, los IECA de la medicación habitual, la vía aérea prevista dificultosa, la vía de abordaje, el carácter de urgencia. Un toque abre el evento con el tipo ya elegido y el motivo escrito arriba, para que la descripción se redacte sabiendo por qué era esperable."}, {"t": "aviso", "clase": "info", "tit": "<b>Ordena, no predice</b>", "cuerpo": ["No registra nada solo, no marca nada y no es un pronóstico: son los que conviene tener a mano. Los que ya se registraron quedan marcados con un tilde para no cargarlos dos veces."]}, {"t": "h3", "txt": "Cuando el acto arranca sin valoración previa"}, {"t": "p", "txt": "Anestesiar sin la valoración cargada pasa, y no siempre por descuido: en una urgencia no hay tiempo, y muchas valoraciones se hacen en papel o en otra institución. Lo que no puede pasar es que quede sin explicación, porque después nadie sabe si faltó la consulta o faltó cargarla."}, {"t": "p", "txt": "El recorrido depende de por dónde se entró, y cada puerta abre lo suyo. Las fichas que ya existen no llevan ninguna marca: se navegan libres, como siempre."}, {"t": "h3", "txt": "Desde «Nueva valoración preanestésica»"}, {"t": "p", "txt": "Se abren <b>Paciente</b> y <b>Preanestesia</b>, y nada más. Los tres pasos del acto quedan cerrados: el acto todavía no existe, y ofrecer sus pantallas es ofrecer formularios vacíos. Se abren solos en cuanto la valoración queda guardada."}, {"t": "h3", "txt": "Desde «Nueva ficha anestésica»"}, {"t": "p", "txt": "Se entra directo a <b>Anestesia</b> y el resto del recorrido queda cerrado. La pantalla muestra una sola cosa: el botón <b>TOMAR ACTO ANESTÉSICO</b>. No hay solapas del acto, no hay botones de Anterior ni Siguiente, y <b>no aparece el cartel de datos esenciales faltantes</b> —enumerar ocho datos que la persona todavía no tuvo oportunidad de cargar no informa, estorba—."}, {"t": "p", "txt": "A partir de ahí la ficha se destraba en tres tiempos, y ninguno se puede saltear:"}, {"t": "tabla", "head": ["", "Qué se resuelve", "Qué se abre"], "rows": [["1", "Tomar el acto anestésico", "Aparece la ventana con los motivos. Quien anestesia ya tiene nombre"], ["2", "Elegir de dónde sale la valoración", "Se habilita <b>Paciente</b>, y la aplicación lleva ahí sola si todavía no hay ninguno"], ["3", "Elegir o cargar el paciente", "Se abre el resto: las cinco solapas del acto, Recuperación, Firmar y el cartel de faltantes"]]}, {"t": "aviso", "clase": "info", "tit": "<b>Por qué el acto se toma antes de saber quién es el paciente</b>", "cuerpo": ["Podría parecer al revés, pero no lo es: tomar el acto es una afirmación sobre <b>uno mismo</b> —soy yo quien se hace cargo—, no sobre el paciente. En una urgencia el responsable se establece antes que la identidad, y eso es exactamente lo que ocurre en la puerta de un quirófano.Mientras no haya paciente, la ficha <b>no se escribe en la base compartida</b>: queda en el equipo y viaja entera cuando se lo elija. Así no quedan fichas fantasma sin nadie adentro si alguien abandona a mitad de camino."]}, {"t": "p", "txt": "El cartel de faltantes vuelve en cuanto el acto se destraba, que es cuando sirve: ahí sí dice qué falta para poder firmar."}, {"t": "h3", "txt": "El cartel de faltantes: sólo lo que quedó atrás, y clickeable"}, {"t": "p", "txt": "El cartel de arriba de la ficha hacía tres cosas mal. Las tres están corregidas."}, {"t": "p", "txt": "<b>Primero: listaba lo que faltaba en el paso donde uno estaba parado.</b> Al entrar a Preanestesia —recién entrar, sin haber tocado nada— un cartel rojo enumeraba ocho cosas de Preanestesia. Claro que faltaban: la persona acababa de llegar. Eso no es información, es ruido, y ruido que además enseña a ignorar el cartel. Ahora <b>el cartel muestra únicamente lo que quedó pendiente de los pasos anteriores</b>. En el paso 1 no aparece nada, porque no hay nada atrás."}, {"t": "p", "txt": "Lo del paso actual se dice en el momento en que corresponde: <b>al tocar «Siguiente»</b>. Ahí aparece un aviso que dice de qué paso estás saliendo y qué le falta —<i>«Salís de «Paciente» sin institución, cirugía»</i>— y aclara que lo vas a seguir viendo arriba, en el paso siguiente, para completarlo cuando quieras. No bloquea: avisa."}, {"t": "p", "txt": "<b>Segundo: la barra de pasos decía FALTA en rojo y no había forma de saber qué faltaba</b> sin volver a entrar al paso a buscarlo. Ahora el cartel del paso siguiente lo nombra con todas las letras, y además el globito de cada paso de la barra lista lo que le falta cuando pasás el mouse por encima."}, {"t": "p", "txt": "<b>Tercero: lo que faltaba era texto muerto.</b> Ahora <b>cada faltante es un botón</b>: lleva al paso donde se carga, cambia a la solapa correcta si es del acto anestésico, abre el punto exacto y deja el campo centrado y con el cursor puesto. Los esenciales van arriba y los opcionales abajo, más tenues."}, {"t": "aviso", "clase": "ok", "tit": "<b>Y te devuelve a donde estabas</b>", "cuerpo": ["Cuando llegás a un paso porque tocaste un faltante, aparece una barra que dice <i>«Viniste desde el paso Preanestesia a completar esto»</i> con un botón <b>Volver a Preanestesia</b>. Completás el dato, volvés de un toque y seguís donde estabas. Sin eso, ir a completar algo te dejaba varado tres pasos atrás teniendo que rehacer el camino a mano."]}, {"t": "p", "txt": "El cartel se recalcula además <b>contra lo que hay en pantalla</b>, no contra lo último guardado: completás un dato y desaparece de la lista en el momento, sin guardar y sin cambiar de paso. El semáforo de los cinco pasos se actualiza igual. Antes, escribías la conclusión de aptitud y el cartel seguía diciendo que faltaba, porque nadie se lo había vuelto a preguntar."}, {"t": "aviso", "clase": "info", "tit": "<b>Y una corrección de fondo</b>", "cuerpo": ["El cartel reclamaba «cirujano» sin parar, aunque estuviera cargado: seguía mirando un campo viejo que dejó de usarse cuando el equipo quirúrgico pasó al paso Anestesia. Ahora mira donde el dato está de verdad, y no lo reclama antes de que la cirugía ocurra: el día de la valoración todavía no se sabe quién opera."]}, {"t": "h3", "txt": "Cada opción lleva a donde se resuelve"}, {"t": "tabla", "head": ["Al elegir…", "La aplicación"], "rows": [["<b>Urgencia o emergencia</b>", "Se queda en el paso 3. El paciente está por entrar y lo que hay que hacer ahora es anestesiar: la valoración se reclama después, con el recordatorio de cada diez minutos"], ["<b>Valoración fuera de la aplicación</b>", "Lleva al paso 2 y baja hasta la tarjeta, con los botones de tomar la foto o elegir el archivo"], ["<b>Ya lo valoré para una intervención anterior</b>", "Muestra las fichas previas de ese paciente, trae la valoración elegida y deja en el paso 2 para revisarla"], ["<b>Procedimiento sin consulta previa</b>", "Pide el tipo y lleva al paso 2, para cargar ahí la evaluación hecha al lado de la camilla"], ["<b>Ninguna: la cargo ahora</b>", "Lleva al paso 2. No declara nada"]]}, {"t": "aviso", "clase": "info", "tit": "<b>Por qué «la cargo ahora» está aparte, en el pie</b>", "cuerpo": ["Las otras cuatro son excepciones: dicen algo que pasó y quedan registradas. «La cargo ahora» no es una excepción, es no tener ninguna — es ir a hacer lo que había que hacer. Ponerla en la misma lista las igualaba, y no están al mismo nivel. Por eso es un botón del pie y no guarda nada."]}, {"t": "h3", "txt": "La reintervención: traer la valoración en vez de rehacerla"}, {"t": "p", "txt": "El paciente vuelve a quirófano a las 48 horas por una complicación. La valoración existe, es de hace dos días y sigue vigente, pero está en <i>otra</i> ficha. Marcar «urgencia» o «hecha fuera de la aplicación» sería falso en los dos casos."}, {"t": "p", "txt": "Con este motivo la aplicación lista las fichas anteriores de ese mismo paciente que ya tienen valoración —con su fecha, cuántos días pasaron, el ASA y quién la hizo— y al elegir una la <b>enlaza</b> y ofrece <b>traerla</b>: antecedentes, examen, laboratorio, escalas y plan pasan a la ficha nueva, editables, para actualizar lo que cambió."}, {"t": "p", "txt": "En la conclusión de aptitud queda escrita la procedencia —<i>«Valoración traída de la ficha del 29/08/2026 (Colecistectomía laparoscópica). Revisar y actualizar lo que cambió»</i>—, para que dentro de un año nadie tenga que adivinar si esa valoración se hizo para esta cirugía o vino de otra."}, {"t": "aviso", "clase": "danger", "tit": "<b>El consentimiento no se copia</b>", "cuerpo": ["Se traen los datos clínicos, no el consentimiento: aquel era de otro procedimiento y de otro riesgo, y la Ley 26.529 lo exige para <b>esta</b> intervención. Por eso, después de traer la valoración, el paso 2 queda en «Falta» hasta que se firme el punto 11 nuevo — que es exactamente lo que corresponde. Tampoco se copian los honorarios: son de aquel acto."]}, {"t": "h3", "txt": "El carácter se declara una sola vez"}, {"t": "p", "txt": "«Urgencia o emergencia» es <b>un solo renglón con dos botones</b>. Son la misma situación —no hubo tiempo de valorar— pero no son lo mismo en la historia clínica, y el botón que se toque carga el <b>carácter de la cirugía</b> en el acto."}, {"t": "p", "txt": "Por eso, al llegar al paso 1, el selector de carácter <b>ya no aparece</b>: en su lugar se lee lo que quedó declarado. Preguntarlo de nuevo treinta segundos después de haberlo dicho es hacer trabajar dos veces. Si hay que corregirlo, se corrige en el paso 3, que es el carácter que se informa y se factura."}, {"t": "h3", "txt": "Urgencia y emergencia: entrar directo al acto"}, {"t": "p", "txt": "En una emergencia el orden real de los hechos es: entra el paciente, se anestesia, y la identidad aparece después —la trae la familia, el documento, el sistema del sanatorio—. Pedir el nombre antes de dejar registrar el acto invierte ese orden y consigue una sola cosa: que el acto se registre de memoria, dos horas más tarde y peor."}, {"t": "p", "txt": "Por eso, declarada la urgencia o la emergencia, la aplicación pregunta <b>por dónde entrar</b>, y las dos salidas son legítimas:"}, {"t": "tabla", "head": ["Opción", "Cuándo"], "rows": [["<b>Entrar directo al acto anestésico</b>", "El paciente entró por la guardia y no se sabe quién es. Abre un <b>NN provisional</b> con la hora de apertura y va derecho al registro: drogas, signos vitales, balance y eventos"], ["<b>Elegir el paciente primero</b>", "El paciente está identificado y elegirlo cuesta diez segundos. Va al paso Paciente, como hasta ahora"]]}, {"t": "aviso", "clase": "danger", "tit": "<b>El NN no es una salida: es una deuda que traba la firma</b>", "cuerpo": ["Mientras el paciente siga siendo provisional, el paso <b>Paciente nunca llega a verde</b>, y sin los cuatro pasos en verde <b>no hay firma</b>. Un cartel rojo lo recuerda en las cinco pantallas de la ficha, con un botón para identificarlo. Deja de ser provisional solo cuando se le cargan apellido real y documento.", "Y sin peso, talla y sexo el vademécum no propone ninguna dosis: es la otra razón por la que los datos del paciente hay que completarlos, aunque sea al terminar."]}, {"t": "p", "txt": "Si al identificarlo resulta que ya estaba en el padrón, se lo elige del desplegable y el NN <b>se borra solo</b> —siempre que ninguna otra ficha lo use—, para no llenar el padrón de NN huérfanos."}, {"t": "h3", "txt": "Importar de una intervención anterior"}, {"t": "p", "txt": "La opción dice <b>«ya fue valorado»</b>, no «ya lo valoré»: puede haberla hecho un colega, y de hecho es lo más frecuente."}, {"t": "p", "txt": "Al elegirla se abre la lista de <b>todas las intervenciones con valoración cargada en la aplicación</b> —propias y de colegas—, con apellido y nombre del paciente, cirugía, fecha, días transcurridos, ASA y quién la valoró, y un buscador por apellido, documento, cirugía o colega."}, {"t": "p", "txt": "<b>Sólo se ofrecen las valoraciones completas</b>"}, {"t": "p", "txt": "La lista filtra por las que están <b>en verde en los pasos Paciente y Preanestesia</b>: con ASA, conclusión de aptitud, plan anestésico y consentimiento firmado. Una valoración a medias no sostiene un acto anestésico —importarla dejaría la ficha nueva igual de incompleta, pero con apariencia de resuelta, que es peor que no importar nada—. Si no hay ninguna, la aplicación lo dice y explica por qué, en vez de mostrar una lista vacía."}, {"t": "p", "txt": "Elegida la intervención de origen, <b>el paciente queda fijado</b>: en el paso 1 aparece con candado, sin desplegable y sin «crear paciente nuevo». Sale de la ficha que se acaba de importar y es la misma persona por definición de reintervención. Sí se puede editar su historia clínica, que es justamente lo que hay que hacer: está internado, en evolución de una cirugía reciente, y el peso, la medicación y los antecedentes cambiaron desde aquella valoración. Si se erró de ficha de origen, se vuelve al paso Anestesia y se elige otra."}, {"t": "p", "txt": "La regla de fondo es la misma que gobierna la firma: <b>no se anestesia sin valoración prequirúrgica, y la valoración lleva el consentimiento informado</b>. La única excepción es la urgencia o la emergencia, donde la valoración se hace diferida o durante el propio acto si el anestesiólogo tiene tiempo — y para eso está el recordatorio de cada diez minutos."}, {"t": "h3", "txt": "El consentimiento nuevo, en su propia ventana"}, {"t": "p", "txt": "La valoración se importa; <b>el consentimiento no</b>. Aquel era de otro procedimiento y de otro riesgo: la Ley 26.529 lo pide para la intervención que se va a hacer. Así que en una reintervención hay que firmar uno nuevo, apoyado en la misma valoración pero con el diagnóstico quirúrgico de hoy."}, {"t": "p", "txt": "Ese consentimiento <b>no obliga a abrir la valoración prequirúrgica</b>. Se abre como una ventana propia desde el mismo paso Anestesia, con un botón en la tarjeta: <i>Completar y firmar el consentimiento de esta intervención</i>. Es el mismo punto 11 —mismo texto legal, mismas declaraciones, mismas dos firmas— pero sin entrar a una valoración que puede ser de un colega."}, {"t": "p", "txt": "El encabezado de la ventana muestra a quién y por qué se firma: apellido, nombre y documento del paciente, la cirugía y el diagnóstico de ahora, y de qué ficha vino la valoración importada. Quien firma tiene que poder ver qué está firmando."}, {"t": "aviso", "clase": "ok", "tit": "<b>El botón espera a que haya diagnóstico</b>", "cuerpo": ["Sale apagado hasta que estén cargadas la cirugía y el diagnóstico de esta intervención: un consentimiento sin procedimiento adentro no dice nada. Por eso, al importar una valoración, la aplicación lleva primero al paso Paciente si esos dos datos faltan.\\u00a0Si es urgencia o emergencia, la salida del artículo 9 está en el mismo desplegable de «Quién firma» y cierra el consentimiento sin firma, documentándolo."]}, {"t": "p", "txt": "<b>Elegir la intervención resuelve también el paciente</b>"}, {"t": "p", "txt": "Como el acto se toma antes de identificar al paciente, en este punto todavía no hay ninguno. El paciente sale de la ficha elegida, que es de donde tiene que salir: por definición de reintervención es la misma persona. Con un solo toque quedan resueltas las dos cosas que faltaban."}, {"t": "h3", "txt": "Ver la ficha anterior sin salir de ésta"}, {"t": "p", "txt": "En la tarjeta queda un botón <b>Ver aquella ficha</b>: abre el documento completo de la intervención de la que se importó —membrete, datos del paciente, valoración entera— en una ventana de <b>sólo lectura</b>, y se cierra con un botón. No lleva a ninguna parte: se sigue en la ficha que se estaba cargando."}, {"t": "p", "txt": "No hay ningún botón para volver a importar. Elegir la intervención <b>es</b> importarla, y ofrecer repetirlo sólo serviría para pisar lo que uno acaba de corregir a mano."}, {"t": "h3", "txt": "La foto de la valoración en papel"}, {"t": "p", "txt": "Con el segundo motivo se puede adjuntar la valoración escaneada o fotografiada, desde la tarjeta que encabeza el paso 2. Entra PDF, JPG, PNG, HEIC del iPhone y Word."}, {"t": "p", "txt": "<b>No pesa ni en la aplicación ni en la base.</b> La ficha guarda únicamente el nombre y el identificador del archivo; los bytes van a una rama aparte que ningún dispositivo escucha en vivo, y se traen de la nube recién cuando alguien abre la foto. En el equipo queda una caché chica con lo último abierto, que se poda sola."}, {"t": "p", "txt": "Las fotos además se achican al guardarlas: una hoja manuscrita se lee perfecto con el lado mayor en 1.400 píxeles. En la prueba, una foto de <b>1.233 KB quedó en 143 KB</b> —nueve veces menos— sin perder la lectura."}, {"t": "aviso", "clase": "warn", "tit": "<b>Primero el paciente, después el archivo</b>", "cuerpo": ["Los dos botones salen apagados hasta que la ficha tenga paciente elegido del padrón. No es un rodeo: el archivo se guarda <b>dentro de la ficha</b>, y una ficha sin paciente todavía no se graba. La foto es el respaldo del papel, no una fuente de datos — la aplicación no puede leer un apellido de una imagen, y sin paciente esa ficha no se podría buscar, ni facturar, ni informar."]}, {"t": "p", "txt": "<b>Adjuntar no es cargar</b>"}, {"t": "p", "txt": "La foto es un respaldo de dónde está el original, no la valoración. La ficha sigue sin poder firmarse hasta que los once puntos del paso 2 estén completos, porque el documento que se le entrega al paciente y el que va a contaduría salen de ahí, no de la foto."}, {"t": "h3", "txt": "El recordatorio, cada diez minutos"}, {"t": "p", "txt": "Terminado el acto —con fecha de cirugía, técnica y fin de anestesia cargados— y con la valoración todavía faltando, aparece un cartel que vuelve <b>cada diez minutos</b>, con tono, hasta que se complete. Se puede <b>posponer una hora</b>."}, {"t": "p", "txt": "Es a propósito más insistente que el de honorarios, que vuelve cada tres horas: ahí lo que se pierde es plata; acá lo que falta es la mitad de la historia clínica de un paciente que ya se anestesió. El mismo aviso aparece además en la campana, y desde ahí se entra directo al paso 2."}, {"t": "p", "txt": "La deuda <b>se salda sola</b>: no hay nada que marcar como hecho. En cuanto el paso Preanestesia llega a verde, desaparecen el cartel, el aviso de la campana y la tarjeta del paso 2."}, {"t": "h3", "txt": "El consentimiento se recuerda dos veces"}, {"t": "p", "txt": "Salir de la Preanestesia sin el punto 11 no se impide —el acto puede estar empezando— pero se avisa, y se avisa dónde va a doler:"}, {"t": "li", "num": false, "txt": "Al tocar <b>Siguiente</b>: <i>«Falta el consentimiento informado (punto 11). Sin él no vas a poder firmar la ficha.»</i>"}, {"t": "li", "num": false, "txt": "Y dentro del <b>paso Anestesia</b>, un cartel permanente arriba de las cinco solapas, con el botón <b>Completar y firmar el consentimiento</b>, que abre la ventana propia sin obligar a entrar a la valoración."}, {"t": "p", "txt": "El segundo importa más de lo que parece: el paso Anestesia es donde se pasa el tiempo. Quien no lo vea ahí se entera recién en Firmar, con el paciente ya en recuperación."}, {"t": "h2", "txt": "Paso 4 · Recuperación"}, {"t": "li", "num": false, "txt": "Hora de ingreso a la <b>URPA</b> y oxigenoterapia. La sigla se aclara arriba de la tarjeta —<b>Unidad de Recuperación Post-Anestésica</b>, la sala de recuperación postanestésica—: se usa cinco veces en el paso y sale impresa en el registro."}, {"t": "li", "num": false, "txt": "Aldrete modificado con los cinco parámetros y puntaje calculado, que avisa si alcanza el criterio de alta."}, {"t": "li", "num": false, "txt": "Dolor en escala visual analógica, con recomendación según el valor."}, {"t": "li", "num": false, "txt": "Náuseas y vómitos, analgesia o antiemético de rescate."}, {"t": "li", "num": false, "txt": "Destino del paciente y estado al egreso."}, {"t": "p", "txt": "Se guarda solo al tocar <b>Siguiente</b>."}, {"t": "h3", "txt": "Dolor y náuseas, separados"}, {"t": "p", "txt": "Estaban en una sola tarjeta, «Dolor y náuseas», y no son lo mismo. El dolor es lo que gobierna la analgesia que el paciente se lleva; las náuseas son un efecto adverso aparte. Juntas, poner «náuseas: no» se leía como si con eso el punto quedara cerrado y no hubiera nada más que indicar."}, {"t": "p", "txt": "Ahora son dos tarjetas. La de <b>Dolor</b> tiene el EVA y la analgesia de rescate que se administró <i>en la URPA</i>, y aclara que el esquema que se lleva el paciente se indica más abajo. La de <b>Náuseas y vómitos</b> tiene su propio antiemético de rescate y su propio aviso: si las presentó, recuerda dejar asentado qué se dio y revisar el esquema de abajo si el paciente se va con opioides; si no las presentó pero el <b>Apfel del punto 5 era de riesgo alto</b>, confirma que la profilaxis cumplió y sugiere continuarla si sigue con opioides en sala."}, {"t": "h3", "txt": "La analgesia postoperatoria se indica acá"}, {"t": "p", "txt": "Estaba en el punto 9 de la valoración prequirúrgica, es decir semanas antes del acto. Ahí se decidía a ciegas: todavía no se sabía cómo iba a salir la cirugía, si el bloqueo iba a funcionar ni con cuánto dolor iba a despertar el paciente. Y una vez escrita, nadie volvía a corregirla."}, {"t": "p", "txt": "Ahora está en <b>Recuperación, inmediatamente después del destino</b>, que es el lugar y el momento en que la indicación se decide de verdad: con el Aldrete y el EVA de esa misma pantalla delante. Lo que se marca acá es la <b>indicación</b>, no el plan."}, {"t": "p", "txt": "La lista pasó de 21 opciones planas a <b>80 agrupadas en nueve bloques plegables</b>: no opioides, opioides sistémicos, coadyuvantes, <b>bloqueos neuroaxiales</b> (peridural lumbar y torácica en bolos y continua, PCEA, morfina intratecal, caudal), <b>bloqueos de tronco y plano fascial</b> (TAP, cuadrado lumbar, ESP, paravertebral, intercostal, PECS I y II, serrato, recto anterior, ilioinguinal, PIF esternal, pudendo, peneano), <b>bloqueos de miembro superior</b> (interescalénico, supraclavicular, infraclavicular, axilar, supraescapular, distales del antebrazo y catéteres continuos), <b>bloqueos de miembro inferior</b> (femoral, canal aductor, PENG, fascia ilíaca, ciático poplíteo y subglúteo, obturador, tobillo y catéteres), <b>analgesia local del sitio quirúrgico</b> (infiltración, catéter de herida, instilación intraperitoneal e intraarticular, anestésico local liposomal) y <b>medidas no farmacológicas y seguimiento</b> (TENS, crioterapia, kinesiología, EVA pautado, plan de rescate escrito). Se agregaron además cuatro campos: duración prevista del esquema, rescate analgésico indicado, esquema detallado y a cargo de quién queda el seguimiento del dolor."}, {"t": "p", "txt": "Arriba de la lista se repite el <b>EVA que el paciente tiene en ese momento</b>, porque es el dato que decide el esquema y estaba tres tarjetas más arriba."}, {"t": "aviso", "clase": "danger", "tit": "<b>Tres avisos que salen solos</b>", "cuerpo": ["<b>Bloqueo neuroaxial en paciente anticoagulado o antiagregado.</b> La aplicación cruza lo que se marca acá con la medicación cargada en el punto 3 y con los antecedentes del punto 1, y avisa en rojo que hay que verificar los intervalos de ASRA/ESAIC antes de la punción y del retiro del catéter. Es la contraindicación que sale más cara y la que se pasaba por alto justamente acá, lejos de donde está cargada la medicación.", "<b>Opioides con STOP-BANG ≥ 5.</b> Recuerda minimizar la dosis, priorizar el bloqueo y los no opioides, y dejar indicado monitoreo prolongado de la saturación en la URPA.", "<b>Ninguna analgesia indicada.</b> Un paciente que sale de la recuperación sin esquema escrito es un paciente sin analgesia: la sala hace lo que dice la indicación. Figura además como faltante en el cartel de arriba de la ficha."]}, {"t": "p", "txt": "Las fichas cargadas antes de la mudanza conservan lo que tenían en el punto 9: aparece propuesto y marcado en Recuperación, con un cartel que lo dice, para confirmarlo o cambiarlo. No se pierde nada y no desaparece de ningún documento ya emitido. En el registro impreso, la analgesia pasó a figurar en la sección de recuperación postanestésica, que es donde se decidió."}, {"t": "h2", "txt": "Paso 5 · Firmar"}, {"t": "p", "txt": "Resumen de toda la anestesia en una pantalla, firma del anestesiólogo y cierre del registro. Se puede adjuntar la foja quirúrgica que redacta el cirujano, sacándole una foto o subiendo el archivo."}, {"t": "p", "txt": "<b>Al firmar, la ficha queda cerrada y en sólo lectura. Se puede reabrir para corregir, y queda constancia en la auditoría de quién la reabrió y cuándo</b>."}, {"t": "p", "txt": "Al guardar, la aplicación hace dos preguntas:"}, {"t": "li", "num": true, "txt": "Si quiere llevarse el registro en un archivo —PDF o Word— o dejarlo sólo guardado."}, {"t": "li", "num": true, "txt": "Si carga <b>el honorario del acto</b> ahora o lo difiere. Si lo difiere, se lo recuerda <b>cada tres horas y con aviso sonoro</b> hasta que lo cargue: campana en rojo y un cartel. <i>El honorario que no se carga en el momento es el que aparece de menos a fin de mes</i>."}, {"t": "h3", "txt": "Cuándo se habilita la firma"}, {"t": "p", "txt": "Una ficha <b>no se puede firmar</b> si alguno de los cuatro pasos anteriores no está en verde. El botón <i>Finalizar y firmar</i> sale apagado, y arriba aparece un cartel rojo que nombra los pasos que faltan cerrar, con un atajo a cada uno."}, {"t": "p", "txt": "Antes se podía firmar igual y el documento salía incompleto. Una historia clínica firmada sin la vía aérea evaluada o sin consentimiento no es un registro incompleto: es un registro que no debería existir. La Ley 26.529 pide que la historia clínica sea completa, y la firma es lo que la cierra."}, {"t": "aviso", "clase": "ok", "tit": "<b>Esto no traba la emergencia</b>", "cuerpo": ["Las dos salidas legítimas del consentimiento —urgencia vital del artículo 9 de la Ley 26.529 y revocación del paciente— ya cuentan como consentimiento completo. Lo que la regla impide no es anestesiar en una emergencia: es firmar sin haberla documentado.", "Vale para <b>todos</b> los casos, incluidos la urgencia y la emergencia: no se firma una ficha sin consentimiento. Lo que cambia en una emergencia no es la exigencia sino la forma de cumplirla — no hay que conseguir firmas, pero sí hay que <b>documentar la excepción</b>, eligiendo <i>No firmado — urgencia vital (art. 9 Ley 26.529)</i> en «Quién firma». Con eso el punto 11 queda completo, el cartel desaparece y la ficha se puede cerrar."]}, {"t": "h3", "txt": "Qué se baja y qué se manda al firmar"}, {"t": "p", "txt": "Al pie del paso 5 hay cuatro botones, y bajan cosas distintas a propósito:"}, {"t": "tabla", "head": ["Botón", "Qué baja"], "rows": [["<b>Honorarios del acto</b>", "Sólo el del acto anestésico. El de la consulta se carga en su propio momento, al pie de la valoración"], ["<b>Word</b> y <b>PDF</b>", "El registro del acto y la recuperación, <b>sin repetir la valoración</b>: son dos documentos y dos honorarios distintos"], ["<b>Word · ficha completa</b>", "Los dos juntos, para el legajo del paciente"]]}, {"t": "p", "txt": "Y el envío a contaduría ofrece dos caminos:"}, {"t": "tabla", "head": ["Envío", "Cuándo"], "rows": [["<b>Enviar sólo el acto</b>", "Lo normal cuando la valoración la hizo un colega y la mandó él, o cuando ya se mandó el día de la consulta"], ["<b>Enviar valoración + acto</b>", "Aparece únicamente cuando los dos actos médicos son tuyos. Manda <b>dos envíos separados</b>, uno a cada bandeja, con su honorario discriminado en cada uno"]]}, {"t": "aviso", "clase": "info", "tit": "<b>«Los dos» no es un envío con dos cosas adentro</b>", "cuerpo": ["Son dos envíos, uno por bandeja, porque separados se facturan. Al contador le llegan discriminados aunque los haya hecho el mismo profesional. Eso no cambió: lo que cambió es que ahora se mandan de una vez."]}, {"t": "h3", "txt": "El recordatorio mira los dos honorarios"}, {"t": "p", "txt": "Antes reclamaba uno solo —el del acto— y sólo si la persona había apretado «lo dejo para después». Se escapaban dos casos enteros: la <b>valoración cerrada y firmada sin el honorario de la consulta</b>, que es un acto médico facturable que no reclamaba nadie, y el acto cerrado sin honorario cuando no se había diferido a propósito."}, {"t": "p", "txt": "Ahora el criterio es uno solo: <b>si el acto médico está concluido y su honorario no tiene modalidad, hay una deuda</b>. El cartel vuelve <b>cada tres horas, con sonido</b>, lista las dos clases de pendiente por separado y lleva a cargar la que se toque. <b>Lo único que lo apaga es cargarlo.</b> Además, al pie del documento que se acaba de emitir aparece el aviso en el momento, que es cuando la persona todavía tiene el caso en la cabeza."}, {"t": "h3", "txt": "Eliminar una ficha: la cuenta regresiva de dos horas"}, {"t": "p", "txt": "Eliminar una ficha borra también su honorario y su facturación, y el contador no se entera: lo que le llegó por un envío queda en su bandeja, pero la ficha de la que salió deja de existir. Es una acción sin vuelta atrás, tomada casi siempre a las apuradas y casi siempre por error."}, {"t": "p", "txt": "<b>Primero: cada uno borra sólo lo que actuó.</b> Antes el botón lo veía cualquiera que pudiera editar la ficha, y borraba todo —en una ficha compartida, uno de los dos podía hacer desaparecer el acto médico del otro—."}, {"t": "tabla", "head": ["Situación", "Qué se puede eliminar"], "rows": [["Los dos actos médicos son míos", "La <b>ficha entera</b>"], ["Valoré yo y nadie tomó el acto todavía", "La <b>ficha entera</b>"], ["Valoró un colega, anestesié yo", "Sólo <b>mi acto</b>: registro, recuperación, firma y mi honorario. La valoración del colega queda intacta y la ficha vuelve a quedar disponible para que otro tome el acto"], ["Valoré yo y anestesió un colega", "<b>Nada.</b> La aplicación dice por qué y a quién le corresponde"], ["Coordinación", "La ficha entera, porque responde por el archivo de la asociación"]]}, {"t": "p", "txt": "<b>Segundo: no se ejecuta en el momento.</b> La ventana avisa que se va a eliminar definitivamente la ficha y su actuación, que se van con ella los honorarios y la facturación, que el contador no tendrá constancia del evento y que sí queda grabado en auditoría. Pide un <b>motivo</b>, que es lo único que va a quedar de esa ficha, y <b>programa la baja para dentro de dos horas</b>."}, {"t": "p", "txt": "Durante esas dos horas la eliminación se detiene con un botón, desde la propia ficha o desde la campana de avisos, donde figura en rojo y arriba de todo con la cuenta regresiva. A los <b>cinco minutos</b> del final suena una <b>alarma</b> —tres notas graves y repetidas, distintas del aviso común— y se abre un cartel con el botón para detenerla. Se avisa una sola vez: si nadie hace nada, se borra."}, {"t": "aviso", "clase": "danger", "tit": "<b>La baja vive en la ficha, no en el dispositivo</b>", "cuerpo": ["Sobrevive a cerrar la aplicación y se ve desde cualquier equipo. La alarma le suena a quien la pidió, que es quien puede detenerla y quien se equivocó; la coordinación la ve en la ficha, sin alarma."]}, {"t": "h3", "txt": "En qué circunstancias un paso queda en «Falta»"}, {"t": "p", "txt": "El rojo no significa «vacío»: para eso está el gris. <b>Falta</b> quiere decir <i>empezado, y le falta algo que no se puede omitir</i>. Cada paso tiene su propia condición:"}, {"t": "tabla", "head": ["Paso", "Está en «Falta» cuando…", "Queda en verde con"], "rows": [["<b>Paciente</b>", "Se cargó la cirugía o la institución, pero falta alguna de las tres", "Paciente, cirugía, institución y diagnóstico"], ["<b>Preanestesia</b>", "Ya están el ASA y la conclusión de aptitud, pero falta el plan anestésico o el consentimiento del punto 11", "ASA, conclusión de aptitud, plan anestésico y consentimiento completo"], ["<b>Anestesia</b>", "Se cargó la técnica, pero falta la fecha real de la cirugía o la hora de fin de anestesia", "Fecha de la cirugía, técnica y fin de anestesia"], ["<b>Recuperación</b>", "Se empezó a cargar, pero el Aldrete está incompleto o falta el destino del paciente", "Aldrete con sus cinco parámetros y destino"], ["<b>Firmar</b>", "Los cuatro anteriores están en verde y sólo falta firmar", "La firma del anestesiólogo"]]}, {"t": "p", "txt": "El caso más frecuente de rojo en <b>Preanestesia</b> es el consentimiento a medio firmar: elegido quién firma, pero sin la firma del paciente o sin la del anestesiólogo. Es también el que más veces impide cerrar la ficha."}]}, {"n": "4", "tit": "Cómo se comparte el trabajo entre colegas", "ico": "pacientes", "coord": false, "b": [{"t": "p", "txt": "Una ficha contiene dos actos médicos distintos, que muchas veces son de dos profesionales: el anestesiólogo 1 hace la valoración prequirúrgica y el anestesiólogo 2 anestesia. Cada uno ve la ficha entera —para anestesiar hay que poder leer el prequirúrgico— pero escribe únicamente en su sección. Lo del otro se muestra atenuado y bloqueado."}, {"t": "h2", "txt": "Las dos secciones de una ficha"}, {"t": "p", "txt": "Una ficha tiene dos secciones —la valoración y el acto— que muchas veces son de dos profesionales. Cuando lo son, arriba del recorrido aparece un conmutador con tres opciones: <b>Valoración prequirúrgica</b>, <b>Acto anestésico</b> y <b>Todo</b>."}, {"t": "p", "txt": "No reparte permisos: los permisos los da la titularidad. Lo que hace es enfocar. Y <b>Todo</b> es el que permite leer la sección del colega, que no es un lujo: para anestesiar hay que poder leer el prequirúrgico, y quien valoró tiene derecho a ver cómo terminó el acto."}, {"t": "p", "txt": "Cuando las dos secciones son de la misma persona —lo habitual— el conmutador <b>no se dibuja</b>: no habría nada que separar, y serían tres botones permanentes para una acción que no existe."}, {"t": "h2", "txt": "Las tres solapas de Fichas"}, {"t": "tabla", "head": ["Solapa", "Qué contiene"], "rows": [["<b>Mías</b>", "Hice la valoración prequirúrgica, el acto anestésico, o los dos"], ["<b>De colegas</b>", "Intervinimos dos: uno valoró y el otro anestesió. Los dos la ven completa, porque los dos la necesitan"], ["<b>Disponibles</b>", "Valoraciones de cualquier socio cuyo acto todavía no tiene anestesiólogo. Se comparten con todos, porque cualquiera puede tener que tomar ese acto: de eso se trata una guardia"]]}, {"t": "p", "txt": "Una ficha en la que nunca intervine y cuyo acto ya tiene dueño no se ve ni se abre. La historia clínica de un paciente ajeno no es asunto de uno."}, {"t": "h2", "txt": "Una valoración a medias no se puede tomar"}, {"t": "p", "txt": "En <b>Disponibles</b> aparecen las valoraciones de cualquier socio cuyo acto todavía no tiene anestesiólogo. Pero no todas se pueden tomar: si la valoración está <b>sin concluir</b>, el acto queda bloqueado."}, {"t": "p", "txt": "En el listado se ve antes de intentarlo — donde diría <i>libre</i> dice <b>valoración sin concluir</b>, en rojo. Y si se intenta igual, la aplicación lo dice con nombre y apellido:"}, {"t": "aviso", "clase": "warn", "tit": "<i>La valoración todavía no está concluida. La hizo **Fernández, Laura** y le falta **la valoración prequirúrgica**. No se puede tomar el acto sobre una valoración a medias: lo que se firma después es una historia clínica incompleta.</i>", "cuerpo": ["Con dos salidas: <b>Cancelar</b> y <b>Avisarle</b>, que abre un hilo interno con el autor, ya titulado con el apellido del paciente."]}, {"t": "p", "txt": "El criterio es el mismo que para importar en una reintervención: los pasos <b>Paciente</b> y <b>Preanestesia</b> en verde. Un solo criterio para las dos cosas que dependen de él."}, {"t": "aviso", "clase": "ok", "tit": "<b>Y se le avisa al que la dejó a medias</b>", "cuerpo": ["El autor recibe un aviso en la campana: <i>«Valoración sin concluir — Pérez, María Elena. Falta la valoración prequirúrgica. Hasta que esté completa, ningún colega puede tomar el acto de esta ficha.»</i> Tocándolo entra directo al paso que falta. Antes esa ficha bloqueaba a otro sin que su autor se enterara nunca."]}, {"t": "p", "txt": "El bloqueo aplica a <b>fichas de otro</b>. La ficha propia nacida por <i>Nueva ficha anestésica</i> sigue permitiendo tomar el acto primero: ahí la valoración se resuelve después, y lo que la exige es la firma."}, {"t": "h2", "txt": "El padrón de pacientes"}, {"t": "p", "txt": "El listado arranca en <b>Mis pacientes</b>: aquellos en los que se intervino, con su historia completa. La otra solapa es el <b>Padrón de la asociación</b>, con todos."}, {"t": "p", "txt": "El padrón existe por una razón práctica: <b>sin él la aplicación se llena de pacientes duplicados</b>. Antes de cargar a alguien hay que poder averiguar si ya está."}, {"t": "h3", "txt": "Qué se ve de un paciente ajeno, y por qué"}, {"t": "p", "txt": "Hay dos cosas que no son lo mismo y la aplicación las separa:"}, {"t": "tabla", "head": ["Qué", "Se ve", "Por qué"], "rows": [["<b>Identificación</b><br>apellido, nombre, documento, fecha de nacimiento, edad, sexo y localidad", "<b>Sí</b>", "Son datos personales, no datos de salud. Sirven para reconocer a la persona y no cargarla dos veces. Sin la edad, dos «Pérez, María» son indistinguibles y el padrón no cumple la única función que tiene."], ["<b>Historia clínica</b><br>antecedentes, medicación, alergias, cobertura y fichas", "<b>No</b>", "Son datos sensibles (Ley 25.326, art. 2 y 8). Sólo los ve quien interviene en ese paciente."]]}, {"t": "h3", "txt": "Por qué está en el padrón y no en «Fichas → Disponibles»"}, {"t": "p", "txt": "Son dos listas que responden preguntas distintas, y confundirlas es fácil. El <b>padrón</b> lista <b>personas</b>: todos los pacientes de la asociación, hayan tenido cirugía o no. <b>Fichas → Disponibles</b> lista <b>trabajo sin dueño</b>: valoraciones que hizo un colega y cuyo acto anestésico todavía no tomó nadie. Que una persona esté en el padrón no dice nada sobre si su acto está libre."}, {"t": "p", "txt": "Para no tener que deducirlo, la ficha de identificación del padrón <b>dice en qué estado está ese paciente</b>. Son cuatro:"}, {"t": "tabla", "head": ["Estado", "Qué significa", "¿Aparece en Disponibles?"], "rows": [["<b>Sin ficha</b>", "Está cargado como persona y nada más. Todavía nadie le hizo una valoración.", "No: no hay ningún acto que tomar."], ["<b>Acto libre</b>", "Tiene valoración de un colega y el acto no lo tomó nadie.", "<b>Sí.</b> La ventana lo dice y trae un botón <b>Ver en Disponibles</b> que lleva a la lista con el paciente ya filtrado."], ["<b>Acto designado</b>", "La valoración designó un anestesiólogo para el acto, y todavía no lo tomó.", "No: ese acto no está libre, es el trabajo de otro colega. La ventana nombra a quién."], ["<b>Ya realizada</b>", "Valoración y acto hechos, o la ficha firmada y cerrada.", "No: no queda nada por tomar."]]}, {"t": "aviso", "clase": "info", "tit": "<b>Se dice el estado y el profesional, no lo que se le hizo</b>", "cuerpo": ["El diagnóstico y la cirugía siguen siendo historia clínica y no se muestran. La única excepción es el <b>acto libre</b>: ahí la cirugía ya figura en Disponibles a la vista de todos los socios, así que nombrarla en la ventana del padrón no agrega ninguna exposición.", "Si el paciente ya fue atendido pero su acto no está libre y necesitás atenderlo igual, el botón <b>Atender a este paciente</b> abre una ficha <b>nueva</b>, tuya. No te mete en la ficha del colega: la ficha es de una intervención, no del paciente, y la misma persona puede tener tres fichas de tres anestesiólogos distintos."]}, {"t": "h3", "txt": "Cómo se accede a un paciente del padrón: atendiéndolo"}, {"t": "p", "txt": "Antes, tocar un paciente ajeno mostraba un aviso que decía «su historia clínica no se abre» y nada más. El padrón avisaba que el paciente ya existía y ahí te dejaba: había que ir igual a cargarlo de nuevo, que es exactamente lo que el padrón venía a evitar."}, {"t": "p", "txt": "Ahora tocarlo abre su <b>ficha de identificación</b>, con los datos de arriba, quién lo atendió antes en la asociación, y dos botones:"}, {"t": "li", "num": false, "txt": "<b>Atender a este paciente</b> — abre una ficha nueva con él ya seleccionado y sus datos cargados: apellido, documento, fecha de nacimiento, peso, talla. No se retipea nada y no se duplica. Desde ese momento su historia queda a tu alcance y el paciente pasa a tu lista de <b>Mis pacientes</b>."}, {"t": "li", "num": false, "txt": "<b>Pedir antecedentes</b> — abre un mensaje interno al colega que ya lo atendió, con el asunto armado. Sirve cuando hace falta el dato antes de tomarlo."}, {"t": "aviso", "clase": "info", "tit": "<b>El acceso se gana atendiendo, no mirando</b>", "cuerpo": ["Ésa es la regla de fondo y no cambió: la historia de un paciente en el que no intervine no es asunto mío (Ley 26.529, art. 2 inc. c). Lo que cambió es que ahora hay una <b>puerta legítima</b>: al abrir una ficha con ese paciente uno pasa a ser interviniente, y el acceso deja de ser curiosidad y pasa a tener causa.", "Queda asentado en la auditoría: <i>«Abre ficha desde el padrón — Coronel, Héctor Daniel»</i>, con quién y cuándo. Es el respaldo del acceso."]}, {"t": "p", "txt": "El selector de paciente del paso 1 ve el padrón entero por la misma razón: para que se pueda elegir a alguien que ya está cargado en vez de crearlo de nuevo."}, {"t": "h2", "txt": "Cuando un paciente vuelve a quirófano"}, {"t": "p", "txt": "Cada intervención es una <b>ficha aparte</b>, con su valoración, su acto y su consentimiento. No se anidan ni se acumulan dentro de una sola: un paciente reoperado tres veces tiene tres fichas, y la valoración de la primera queda intacta en la suya. Un documento firmado no se modifica retroactivamente ni se le cuelgan cosas encima."}, {"t": "p", "txt": "Para no tener que deducirlo de las fechas, la aplicación las <b>numera</b>. En el encabezado de la ficha, debajo del nombre del paciente:"}, {"t": "aviso", "clase": "info", "tit": "<b>2.ª intervención de 2 · la anterior fue el 27/08/2026</b>", "cuerpo": []}, {"t": "p", "txt": "Y en la historia del paciente cada ficha lleva su número delante de la cirugía. Con una sola intervención no aparece nada: decir <i>1.ª de 1</i> no informa."}, {"t": "aviso", "clase": "info", "tit": "<b>El número se calcula, no se guarda</b>", "cuerpo": ["Sale del orden por fecha entre las fichas de ese paciente. Si se borra una ficha o se corrige una fecha, la numeración se reacomoda sola. Un contador guardado quedaría mintiendo a la primera corrección."]}, {"t": "p", "txt": "El vínculo entre una reintervención y la anterior queda además asentado de forma explícita: la ficha guarda de cuál importó la valoración, así la cadena es rastreable años después."}, {"t": "h2", "txt": "Las dos fechas de una ficha"}, {"t": "p", "txt": "Una ficha tiene dos fechas y casi nunca coinciden:"}, {"t": "li", "num": false, "txt": "<b>Fecha de valoración</b> — el día de la consulta prequirúrgica. Es el mes en que se factura e informa esa consulta."}, {"t": "li", "num": false, "txt": "<b>Fecha de cirugía</b> — el día del acto anestésico, cargada en el paso 3. Es el mes en que se factura e informa el acto."}, {"t": "p", "txt": "Mezclarlas rompe la facturación: una valoración de marzo con cirugía en abril iría entera a marzo, y el honorario del acto aparecería en el mes equivocado, a excepción que sea urgencia/emergencia."}, {"t": "h2", "txt": "Los dos caracteres"}, {"t": "p", "txt": "Con el carácter pasa lo mismo que con la fecha, y por la misma razón: recién se sabe de verdad el día del acto."}, {"t": "li", "num": false, "txt": "<b>Carácter de la cirugía</b> — cómo se la vio en la consulta prequirúrgica. Describe esa consulta, y es el que alimenta el ARISCAT que se imprime en la valoración."}, {"t": "li", "num": false, "txt": "<b>Carácter del acto</b> — en qué condición se anestesió realmente. Se confirma en el paso 3 y es el que se informa en las estadísticas y el que sostiene el adicional de urgencia del honorario."}, {"t": "p", "txt": "Una valoración hecha en consultorio como programada puede terminar en una cirugía adelantada por una perforación. Los dos hechos son ciertos y la aplicación los guarda por separado: corregir el del paso 1 reescribiría hacia atrás el contexto de un documento ya firmado."}, {"t": "p", "txt": "En el paso 3 el carácter viene <b>propuesto</b> con el de la valoración, y así queda marcado hasta que el anestesiólogo lo toca. Si lo confirma con un valor distinto, la ficha lo dice y el PDF del acto lo imprime así: <i>Carácter: EMERGENCIA (en la valoración: urgencia)</i>."}, {"t": "tabla", "head": ["Valoración", "Acto", "Qué pasa"], "rows": [["Programada", "Programada", "Caso normal, sin ruido en pantalla"], ["Programada", "Urgencia o emergencia", "Se adelantó. Queda asentado el cambio y se informa y factura como no programada"], ["Urgencia", "Programada", "Se destrabó y se operó en frío. Queda asentado igual"], ["Urgencia", "Emergencia", "Escaló. El adicional del nomenclador es el mismo +50 %"], ["Emergencia", "Urgencia o programada", "Se compensó y pudo esperar"]]}, {"t": "h2", "txt": "Dos actos médicos, dos honorarios"}, {"t": "p", "txt": "Cada honorario se carga en su propio momento y en su propia ventana: el de la consulta al pie de la valoración, el del acto al firmar. Se guardan por separado, viajan a contaduría en <b>dos envíos distintos</b> y se discriminan en cada uno, aunque los dos sean del mismo profesional."}, {"t": "h3", "txt": "Y cada uno elimina sólo lo suyo"}, {"t": "p", "txt": "La misma regla gobierna la baja de una ficha: <b>nadie elimina lo que no actuó</b>. Si valoraste vos y anestesió un colega, no podés borrar la ficha —borrarías el registro de un acto médico ajeno, con su honorario—; la aplicación te dice a quién le corresponde. Si anestesiaste vos sobre la valoración de un colega, eliminás tu acto y la valoración de él queda en pie. Ver el detalle en el capítulo 3, paso 5."}, {"t": "tabla", "head": ["Concepto", "Titular", "Se imputa a"], "rows": [["<b>Consulta prequirúrgica</b>", "Quien hizo la valoración", "El mes de la valoración"], ["<b>Acto anestésico</b>", "Quien anestesió", "El mes de la cirugía"]]}]}, {"n": "5", "tit": "Guías, protocolos y calculadoras", "ico": "guias", "coord": false, "b": [{"t": "p", "txt": "Es un módulo entero de la aplicación y es de los que más se usan en el quirófano, porque se consulta con una mano y en segundos."}, {"t": "p", "txt": "Se entra por <b>Gestión → Guías</b>, o desde el acceso directo del panel de inicio."}, {"t": "aviso", "clase": "warn", "tit": "<b>Lo primero que dice la pantalla</b>", "cuerpo": ["Material de consulta rápida. No reemplaza el juicio clínico ni la lectura de la guía original. Verificá dosis y disponibilidad en tu institución antes de aplicarlas."]}, {"t": "h2", "txt": "5.1 · Las quince guías"}, {"t": "p", "txt": "Son una síntesis operativa de las recomendaciones de ASA, DAS, ASRA, MHAUS, ESAIC, ACC/AHA, OMS y ERAS. Cada una se despliega en secciones con viñetas; ninguna ocupa más de una pantalla."}, {"t": "tabla", "head": ["Guía", "Fuente", "Categoría"], "rows": [["Vía aérea difícil — algoritmo operativo, plan A-B-C-D y CICO", "DAS / ASA", "Crítico"], ["LAST — toxicidad sistémica por anestésicos locales", "ASRA", "Crítico"], ["Hipertermia maligna — protocolo", "MHAUS", "Crítico"], ["Anafilaxia perioperatoria", "Consenso", "Crítico"], ["Neuroeje y anticoagulantes — intervalos", "ASRA", "Regional"], ["Ayuno preoperatorio y profilaxis de aspiración", "ASA 2023", "Preoperatorio"], ["Evaluación cardiovascular preoperatoria", "ACC/AHA 2024", "Preoperatorio"], ["Lista de verificación de seguridad quirúrgica", "OMS", "Seguridad"], ["Estándares de monitoreo básico", "ASA", "Seguridad"], ["Náuseas y vómitos postoperatorios — profilaxis", "Consenso 4.ª ed.", "Manejo"], ["Trombo profilaxis perioperatoria", "Consenso", "Manejo"], ["Manejo de sangre del paciente y transfusión", "Consenso", "Manejo"], ["Dosis de referencia del adulto", "—", "Farmacología"], ["Referencias pediátricas", "—", "Pediatría"], ["ERAS — recuperación mejorada tras la cirugía", "ERAS Society", "Protocolo"]]}, {"t": "p", "txt": "Arriba de la lista hay un <b>buscador</b> que filtra por cualquier palabra del título o del cuerpo —«dantrolene», «ayuno», «ASRA», «LAST»— y cuatro accesos directos a las cuatro guías críticas, que son las que se necesitan cuando no hay tiempo de buscar nada."}, {"t": "img", "src": "manual/m7.jpg"}, {"t": "h2", "txt": "5.2 · Las calculadoras"}, {"t": "p", "txt": "Se abren con el quinto acceso directo, el de color agua. Se cargan <b>peso</b> —lo único obligatorio—, talla, edad, sexo y, si se quiere calcular sangrado permisible, el hematocrito inicial y el mínimo aceptable. Todo se recalcula mientras se escribe."}, {"t": "h3", "txt": "Lo que calcula sobre el paciente"}, {"t": "tabla", "head": ["Medida", "Cómo"], "rows": [["<b>IMC</b>", "Con su clasificación"], ["<b>Superficie corporal</b>", "Fórmula de Mosteller"], ["<b>Peso ideal</b>", "Fórmula de Devine. Es el que hay que usar para dosificar relajantes y para el volumen tidal"], ["<b>Volemia estimada</b>", "Ajustada por edad y sexo: 85 ml/kg en el lactante, 75 en el niño, 70 en el varón adulto, 65 en la mujer"], ["<b>Pérdida sanguínea permisible</b>", "Hasta el hematocrito mínimo indicado"], ["<b>Mantenimiento hídrico</b>", "Regla 4-2-1"], ["<b>Volumen </b><b>tidal</b><b> protector</b>", "6 a 8 ml/kg de peso ideal"], ["<b>Tubo endotraqueal</b>", "En menores de 16 años, con balón y sin balón, más la profundidad"]]}, {"t": "h3", "txt": "Lo que calcula en dosis"}, {"t": "p", "txt": "Propofol de inducción, fentanilo, rocuronio —con la dosis de secuencia rápida discriminada—, succinilcolina, sugammadex en sus tres escenarios (bloqueo moderado, profundo y reversión inmediata), ketamina, dosis máximas de lidocaína —con y sin adrenalina—, bupivacaína y ropivacaína con su equivalente en mililitros de la concentración habitual, ácido tranexámico y adrenalina en paro, con la dosis pediátrica cuando corresponde."}, {"t": "aviso", "clase": "danger", "tit": "<b>Las dos urgencias, calculadas para ese paciente</b>", "cuerpo": ["Al pie, la calculadora resuelve las dos emergencias en las que nadie quiere estar haciendo cuentas: el <b>rescate lipídico por LAST</b> —bolo, infusión, máximo acumulado y tope de adrenalina— y el <b>dantrolene</b> en hipertermia maligna, con la dosis inicial, el número de viales de 20 mg que hay que reconstituir y el techo habitual. Todo expresado en mililitros y en viales, que es la unidad en la que se trabaja."]}]}, {"n": "6", "tit": "Comunicación interna", "ico": "correo", "coord": false, "b": [{"t": "p", "txt": "Es la vía por la que se resuelven la mitad de las cosas que antes iban por WhatsApp."}, {"t": "p", "txt": "Se entra por <b>Asociación → Mensajes</b>. En el teléfono, el aviso de mensajes pendientes viaja en Ajustes, que es por donde se entra."}, {"t": "h2", "txt": "6.1 · Tres tipos y tres prioridades"}, {"t": "tabla", "head": ["Tipo", "Qué significa"], "rows": [["<b>Reclamo</b>", "Requiere respuesta y seguimiento hasta resolverse"], ["<b>Consulta</b>", "Pregunta o pedido de información"], ["<b>Aviso</b>", "Comunicación informativa, no exige respuesta"]]}, {"t": "p", "txt": "La prioridad —Alta, Normal o Baja— es independiente del tipo y sólo afecta a cómo se marca el hilo en el listado."}, {"t": "h2", "txt": "6.2 · Con quién se puede hablar"}, {"t": "p", "txt": "Los destinatarios posibles son cualquier socio habilitado, la <b>Coordinación AFAAR</b> y el <b>Contable AFAAR</b>. Un hilo puede tener varios destinatarios."}, {"t": "p", "txt": "Coordinación y Contable son roles institucionales fijos: se ofrecen siempre, aunque todavía no hayan entrado nunca desde ningún dispositivo. El mensaje queda esperándolos, como un correo."}, {"t": "aviso", "clase": "ok", "tit": "<b>Un hilo lo ven únicamente sus participantes</b>", "cuerpo": ["Ni la coordinación ni el contador leen conversaciones ajenas. No hay un buzón general ni una bandeja de supervisión: si alguien no está en el hilo, ese hilo no existe para él."]}, {"t": "h2", "txt": "6.3 · La regla de las dos horas"}, {"t": "p", "txt": "Un hilo abierto que espera <b>mi</b> respuesta y lleva más de dos horas sin que yo conteste se marca en rojo en el listado, se cuenta en la campana del encabezado y encabeza la pantalla con un aviso. El contador simétrico también existe: si soy yo el que abrió un reclamo y nadie me contestó en dos horas, la aplicación me lo dice."}, {"t": "p", "txt": "Los avisos no entran en esta cuenta —no exigen respuesta— y los hilos dados por resueltos tampoco."}, {"t": "p", "txt": "El listado tiene cuatro indicadores arriba: <b>Sin leer</b>, <b>Abiertos</b>, <b>Esperan tu respuesta</b> y <b>Sin respuesta ajena</b>; y un filtro con las mismas cinco vistas más Resueltos."}, {"t": "h2", "txt": "6.4 · Cómo se trabaja un hilo"}, {"t": "li", "num": true, "txt": "Se abre con <b>Nuevo mensaje</b>: destinatarios, tipo, prioridad, asunto y texto."}, {"t": "li", "num": true, "txt": "Al enviar, el hilo se cierra y vuelve al listado, indicando de quién es el turno. La caja de respuesta aparece sólo cuando el otro contestó: no se puede escribir dos veces seguidas y convertir un reclamo en un monólogo."}, {"t": "li", "num": true, "txt": "Cuando el asunto se resolvió, cualquiera de los participantes lo marca como <b>resuelto</b>. Se puede reabrir, y tanto el cierre como la reapertura quedan en la auditoría."}, {"t": "aviso", "clase": "danger", "tit": "<b>No se cargan datos de paciente</b>", "cuerpo": ["La aplicación lo avisa expresamente en la pantalla de composición. El canal es administrativo y el contable participa de esos hilos: no está habilitado a acceder a datos de salud, y un nombre de paciente escrito en un reclamo de cobranza es exactamente eso. Para referirse a una prestación alcanza con el mes, el financiador y el importe."]}, {"t": "h2", "txt": "6.5 · Los dos atajos del portal contable"}, {"t": "p", "txt": "El portal del contador tiene dos botones que abren un hilo con la coordinación ya titulado, porque son las dos conversaciones que se repiten todos los meses:"}, {"t": "li", "num": false, "txt": "En <b>Cartera y deuda</b>, «Abrir reclamo interno» → <i>Gestión de cobranza — saldos vencidos</i>."}, {"t": "li", "num": false, "txt": "En <b>Recomendaciones</b>, «Comunicar estas conclusiones» → <i>Informe de cobranzas y situación fiscal</i>."}, {"t": "img", "src": "manual/m8.jpg"}, {"t": "h2", "txt": "6.6 · La campana: avisos y recordatorios"}, {"t": "p", "txt": "La campana del encabezado no es lo mismo que los mensajes. Los mensajes son conversaciones entre personas; la campana son cosas que la aplicación detecta sola mirando tus fichas: cirugías de hoy y de mañana, valoraciones sin acto, actos sin firmar, honorarios que dejaste para después, datos esenciales sin cargar."}, {"t": "aviso", "clase": "info", "tit": "<b>Los avisos no se leen: se resuelven</b>", "cuerpo": ["Abrir la campana no los apaga. No hay «marcar como visto», porque no son notificaciones: son el estado real de tus fichas, recalculado cada vez que se abre la ventana. Un aviso desaparece cuando desaparece su causa —cuando cargás el dato que faltaba, firmás la ficha o cargás el honorario— y no antes. Es deliberado: un recordatorio que se apaga porque lo miraste no recuerda nada."]}, {"t": "p", "txt": "Cada renglón de la lista es un atajo: al tocarlo se abre la ficha en el paso exacto donde está el problema, o directamente en la ventana de honorarios."}, {"t": "h3", "txt": "Las dos maneras de enterarte sin estar mirando la pantalla"}, {"t": "p", "txt": "Al pie de la ventana hay dos casillas, y son cosas distintas:"}, {"t": "tabla", "head": ["Casilla", "Qué hace", "De qué depende"], "rows": [["<b>Avisarme con una notificación del sistema</b>", "Al abrir la app te recuerda las cirugías del día y del día siguiente, con un aviso del sistema operativo", "Del permiso del navegador. No se tilda sola: se pide el permiso y la casilla queda reflejando lo que el navegador haya contestado"], ["<b>Sonar un tono al abrir la app cuando haya algo pendiente</b>", "Dos notas cortas al entrar, una sola vez por apertura, si hay avisos, recordatorios o mensajes sin ver", "De nada externo. Funciona sin conexión y sin permisos, y queda guardada en cada dispositivo por separado"]]}, {"t": "p", "txt": "Si el navegador bloqueó las notificaciones en su momento, ya no vuelve a preguntar: la casilla queda gris y la propia ventana explica que se destraban desde el candado de la barra de direcciones, en Notificaciones → Permitir. En iPhone y iPad las notificaciones del sistema sólo funcionan con la aplicación agregada a la pantalla de inicio."}, {"t": "aviso", "clase": "ok", "tit": "<b>Sobre el tono</b>", "cuerpo": ["Se sintetiza en el navegador, así que no hay ningún archivo de sonido que descargar y suena también con la aplicación instalada y sin señal. Los navegadores no dejan sonar antes de que la persona toque la pantalla: si el primer intento queda bloqueado, el tono espera al primer toque y suena una sola vez. Junto con el tono aparece un cartel que dice cuántas cosas hay pendientes de resolver."]}, {"t": "p", "txt": "Además de los avisos que se resuelven solos, hay <b>dos carteles que vuelven a aparecer</b> por su cuenta mientras la aplicación esté abierta:"}, {"t": "tabla", "head": ["Cartel", "Cada cuánto", "Hasta cuándo"], "rows": [["<b>Honorarios que dejaste para después</b>", "Tres horas", "Hasta que se carga la modalidad del acto"], ["<b>Falta completar la valoración prequirúrgica</b>", "Diez minutos, con tono", "Hasta que el paso Preanestesia queda en verde. Se puede posponer una hora"]]}]}, {"n": "7", "tit": "El coordinador", "ico": "escudo", "coord": false, "b": [{"t": "p", "txt": "El portal de coordinación tiene cinco secciones. La puesta a punto inicial —lo que hay que hacer una sola vez, antes del primer paciente— está en el capítulo 2; acá está el trabajo de todos los meses."}, {"t": "h2", "txt": "Solicitudes"}, {"t": "p", "txt": "Altas de socios pendientes de aprobación. Se verifica matrícula y comprobante y se aprueba o se rechaza. También se puede suspender, reactivar o restablecer la contraseña de un socio."}, {"t": "p", "txt": "El número de solicitudes pendientes aparece como un globo rojo sobre «Coordinación» en el menú, para que no queden esperando."}, {"t": "h2", "txt": "Padrón de socios"}, {"t": "p", "txt": "Listado completo de los anestesiólogos habilitados, con su matrícula, sus datos fiscales y su estado. El <b>CUIT</b> y la <b>condición frente al IVA</b> de cada socio se cargan acá o en el perfil de cada uno, y el portal contable los reclama si faltan: sin CUIT no se puede emitir el comprobante."}, {"t": "h2", "txt": "Prestadores"}, {"t": "p", "txt": "Financiadores e instituciones. Se edita haciendo clic en cualquier renglón de la tabla —toda la fila es un botón—. El detalle de los campos está en el capítulo 2."}, {"t": "p", "txt": "Hay <b>detector de duplicados</b>: si alguien cargó «OSDE» y otro «O.S.D.E.», la aplicación lo detecta y ofrece fusionarlos —todas las fichas y pacientes pasan al nombre elegido— o marcarlos como distintos."}, {"t": "aviso", "clase": "info", "tit": "<b>Un prestador que ya se usó no se borra: se da de baja</b>", "cuerpo": ["Deja de ofrecerse en los desplegables, pero las fichas históricas conservan el nombre con el que se emitieron. Un documento firmado no se cambia retroactivamente."]}, {"t": "h2", "txt": "Catálogos"}, {"t": "p", "txt": "Valores de la unidad anestésica por financiador, el listado de lo que los socios agregaron a mano —antecedentes patológicos y cirugías que no estaban en el catálogo de base—, y la carga o el borrado de los datos de demostración."}, {"t": "h2", "txt": "Auditoría"}, {"t": "p", "txt": "Registro de accesos y cambios: quién vio y quién modificó cada cosa, con fecha y hora. Responde la pregunta «quién abrió esta historia clínica y cuándo», que es la trazabilidad que pide la Ley 25.326 y lo único que respalda al profesional si se discute quién modificó qué."}, {"t": "p", "txt": "En el dispositivo se guardan los últimos 5.000 eventos. Al pasar ese número, los más viejos se archivan como planilla CSV en la carpeta «AFAAR — Auditoría» del Drive de la asociación y recién entonces se sacan del equipo. Si el archivado falla, no se borra nada y se reintenta. Hay además un botón para descargar el CSV completo sin depender de Google."}, {"t": "h2", "txt": "Sincronización y respaldos"}, {"t": "p", "txt": "Se abre tocando el indicador del encabezado, que dice <b>En línea</b> cuando la base compartida está conectada y <b>Local</b> cuando no. Desde ahí se descarga el respaldo completo en JSON."}, {"t": "aviso", "clase": "danger", "tit": "<b>El respaldo contiene historias clínicas</b>", "cuerpo": ["Guardarlo cifrado, nunca en un repositorio público ni en una carpeta compartida abierta. La Ley 25.326 considera los datos de salud como datos sensibles, y la Ley 26.529 obliga a conservarlos un mínimo de diez años."]}, {"t": "img", "src": "manual/m9.jpg"}]}, {"n": "8", "tit": "El contable", "ico": "dinero", "coord": false, "b": [{"t": "p", "txt": "Capítulo de seis solapas y una lógica propia que no es evidente."}, {"t": "h2", "txt": "8.1 · Qué ve y qué no"}, {"t": "p", "txt": "El portal contable es <b>económico, no clínico</b>. El contable no es personal de salud y la Ley 25.326 no lo habilita a acceder a datos de salud, así que la aplicación se lo impide por diseño: sus pantallas se alimentan de una proyección anonimizada de las prestaciones —importes, financiadores, instituciones y profesionales— y ninguna de ellas incluye pacientes, cirugías, diagnósticos ni evolución."}, {"t": "p", "txt": "La propia pantalla lo declara arriba de todo, en un aviso permanente. No es una restricción que se pueda levantar desde una opción: los campos clínicos no llegan a ese portal."}, {"t": "h2", "txt": "8.2 · Los filtros gobiernan las seis solapas"}, {"t": "p", "txt": "Arriba de todo hay cuatro filtros que se aplican a todas las pantallas a la vez: <b>Desde</b> y <b>Hasta</b> (mes y año; por defecto, los últimos doce meses), <b>Anestesiólogo</b> e <b>Institución</b>. Cambiar el período y olvidarse de que quedó cambiado es el error más común al empezar a usar el portal: si un número no cierra, lo primero que hay que mirar es la franja de filtros."}, {"t": "h2", "txt": "8.3 · Quién marca presentado, facturado y cobrado"}, {"t": "aviso", "clase": "warn", "tit": "<b>El contador no marca los estados. </b><b>Los marca</b><b> el anestesiólogo.</b>", "cuerpo": ["Es lo primero que hay que entender del portal, porque cambia todo el circuito de trabajo. El portal contable <b>lee</b>; no escribe sobre las prestaciones. Lo único que el contador carga son los parámetros de la solapa 6."]}, {"t": "p", "txt": "Los cinco estados de una prestación son:"}, {"t": "tabla", "head": ["Estado", "Qué significa", "Cuenta como impaga"], "rows": [["<b>Pendiente</b>", "Devengada pero todavía no presentada a cobro", "Sí"], ["<b>Presentado</b>", "Presentada al financiador; desde acá corren los días de deuda", "Sí"], ["<b>Facturado</b>", "Con comprobante emitido", "Sí"], ["<b>Cobrado</b>", "Con el cobro imputado", "No"], ["<b>Débito / rechazado</b>", "El financiador la debitó o la rechazó", "Sí"]]}, {"t": "p", "txt": "Se cargan desde la ficha, con el botón <b>Honorarios</b>, que se habilita al guardar la valoración. La ventana tiene dos bloques, y cada uno lo edita su titular:"}, {"t": "li", "num": false, "txt": "El bloque de la <b>consulta prequirúrgica</b> lo edita quien hizo la valoración."}, {"t": "li", "num": false, "txt": "El bloque del <b>acto anestésico</b> lo edita quien anestesió."}, {"t": "li", "num": false, "txt": "El que no le corresponde a uno aparece atenuado, bloqueado y rotulado «no es tuya» o «no es tuyo». <i><b>El coordinador puede editar los dos</b></i>."}, {"t": "p", "txt": "En cada bloque se carga: <b>Estado</b>, <b>Fecha de presentación</b>, <b>N.º de comprobante</b> y <b>Monto cobrado</b>; en el del acto, además, <b>Observaciones administrativas</b> —débitos, reclamos, auditoría del financiador, número de expediente—."}, {"t": "p", "txt": "El <b>saldo</b> es la resta entre el monto y lo cobrado. Los <b>días de deuda</b> se cuentan desde la fecha de presentación y, si no hay ninguna cargada, desde la fecha de la prestación: por eso una prestación que nunca se presentó igual envejece."}, {"t": "p", "txt": "El circuito real, entonces, es este: el contador detecta el atraso o el dato faltante en su portal y abre un reclamo interno pidiéndole al profesional que lo complete. Es deliberado: el estado lo declara quien emitió el comprobante y responde por él."}, {"t": "img", "src": "manual/m10.jpg"}, {"t": "h3", "txt": "El cruce con el carácter del acto"}, {"t": "p", "txt": "El adicional de <b>urgencia / emergencia (+50 %)</b> <b>viene tildado</b> cuando el acto está registrado como urgencia o emergencia. Es un cambio de criterio deliberado: antes no se tildaba nunca —el argumento era que el recargo depende del convenio y no sólo del carácter— y el resultado fue que el honorario que se perdía era siempre el mismo, el del acto de las cuatro de la mañana que se facturó a fin de mes sin acordarse del carácter."}, {"t": "p", "txt": "Sigue siendo una <b>propuesta y no una decisión de la máquina</b>: la casilla llega marcada como propuesta, con un cartel que explica por qué, y se destilda con un clic si el convenio no lo reconoce. Sólo se propone <b>la primera vez</b> que se abre la ventana; una vez guardado el honorario, manda lo guardado y la aplicación no vuelve a tocar nada. Y el aviso de contradicción sigue funcionando en los dos sentidos:"}, {"t": "li", "num": false, "txt": "Acto registrado como urgencia o emergencia y el adicional <b>sin tildar</b> → aviso ámbar, con el importe concreto que se está dejando de facturar."}, {"t": "li", "num": false, "txt": "Adicional <b>tildado</b> y acto registrado como programado → aviso rojo. Un recargo sin respaldo en el registro es lo primero que debita una auditoría del financiador."}, {"t": "p", "txt": "El aviso vive en la ventana de honorarios porque es donde los dos datos se ven juntos. Al <b>portal contable</b> el carácter no llega, por la lista blanca del punto 8.1; pero sí llega en el <b>envío a contaduría</b>, que es documentación clínica cedida envío por envío: ahí figura antes del honorario y, cuando no es programado, dice «con adicional»."}, {"t": "h3", "txt": "Cómo se calcula el honorario del acto"}, {"t": "p", "txt": "Según la <b>modalidad de convenio</b>: convenio abierto (por unidades), convenio cerrado (módulo), convenio capitado, particular, relación de dependencia o sin cargo. En el convenio abierto el total sale de las unidades anestésicas por el valor de la unidad del financiador, más los adicionales del nomenclador que correspondan:"}, {"t": "tabla", "head": ["Adicional", "%", "Adicional", "%"], "rows": [["Urgencia / emergencia", "+50", "ASA V", "+50"], ["Horario nocturno (22 a 06 h)", "+50", "Menor de 1 año o mayor de 80", "+25"], ["Sábado tarde, domingo o feriado", "+50", "Obesidad mórbida (IMC ≥ 40)", "+25"], ["ASA III-IV", "+25", "Prolongación (cada 30 min extra)", "+15"], ["Monitoreo invasivo / línea arterial o PVC", "+20", "Bloqueo analgésico complementario", "+20"]]}, {"t": "p", "txt": "La consulta prequirúrgica tiene su propia modalidad —por obra social, particular, incluida en el acto, cubierta por la institución o sin cargo— y su importe se completa solo con el valor de consulta cargado para ese financiador."}, {"t": "h2", "txt": "8.4 · Solapa 1 — Tablero"}, {"t": "p", "txt": "El resumen del período filtrado, en cuatro indicadores: <b>Devengado</b>, <b>Cobrado</b> con su porcentaje sobre el devengado, <b>Adeudado</b> y <b>Deuda a hoy</b> ajustada por IPC."}, {"t": "p", "txt": "Debajo, un aviso cuantifica la <b>pérdida por exposición a la inflación</b>: lo que la asociación resignó en poder adquisitivo por cobrar tarde. Si algún saldo abarca meses sin IPC cargado, el aviso lo dice, porque en ese caso el ajuste está subestimado."}, {"t": "p", "txt": "Después, dos tarjetas —inflación acumulada y proyectada, y antigüedad de la deuda por tramos— y tres tablas con la misma estructura: por anestesiólogo, por institución y por financiador, con N.º, devengado, cobrado, adeudado, valor a hoy y porcentaje de cobranza."}, {"t": "p", "txt": "Al pie, <b>Exportar a Excel</b> e <b>Informe PDF</b>."}, {"t": "h2", "txt": "8.5 · Solapa 2 — Cartera y deuda"}, {"t": "p", "txt": "Sólo las prestaciones impagas, ordenadas de más vieja a más nueva. Cuatro indicadores: deuda total, deuda <b>morosa</b> (pasado el umbral de mora), deuda <b>incobrable</b> (pasado el umbral de incobrabilidad) y días promedio de antigüedad. Los dos umbrales se configuran en Parámetros."}, {"t": "p", "txt": "El detalle muestra, renglón por renglón: mes, concepto (consulta o acto), profesional, institución, financiador, saldo, días de antigüedad, valor a hoy y estado. La antigüedad se agrupa además en seis tramos:"}, {"t": "tabla", "head": ["Tramo", "Lectura"], "rows": [["<b>Al día (0 a 30 días)</b>", "Dentro del plazo normal de pago"], ["<b>31 a 60 días</b>", "Seguimiento: confirmar que la presentación fue recibida y conformada"], ["<b>61 a 90 días</b>", "Ya es mora"], ["<b>91 a 180 días</b>", "Mora consolidada"], ["<b>181 a 365 días</b>", "La probabilidad de cobro cae fuerte"], ["<b>Más de un año</b>", "Candidata a previsión por incobrabilidad"]]}, {"t": "p", "txt": "Al pie, <b>Exportar deuda</b> y <b>Abrir reclamo interno</b>, que abre un hilo con la coordinación titulado «Gestión de cobranza — saldos vencidos»."}, {"t": "h2", "txt": "8.6 · Solapa 3 — Indexación"}, {"t": "p", "txt": "Toma la deuda impaga y la lleva a moneda de hoy, discriminada por anestesiólogo, por institución y por financiador. Cuatro columnas:"}, {"t": "tabla", "head": ["Columna", "Qué es"], "rows": [["<b>Nominal</b>", "El saldo tal como fue facturado"], ["<b>A hoy</b>", "El nominal por el coeficiente de IPC acumulado desde el mes de la prestación hasta el corriente. Se compone mes a mes: (1+i₁) × (1+i₂) × …"], ["<b>Pérdida</b>", "La diferencia entre ambos. Es el poder adquisitivo que se resignó por cobrar tarde"], ["<b>Proyectado 12 m</b>", "El valor a hoy llevado doce meses más con la inflación proyectada. Responde a «si esto se cobra recién dentro de un año, ¿cuánto habría que reclamar?»"]]}, {"t": "p", "txt": "El coeficiente de proyección anual sale de anualizar el promedio mensual de los últimos seis meses cargados. Sirve para dimensionar, no para pronosticar la inflación."}, {"t": "aviso", "clase": "warn", "tit": "<b>La solapa avisa qué meses de IPC faltan</b>", "cuerpo": ["Y los nombra uno por uno. Sin la serie completa, toda la indexación del portal queda subestimada y las recomendaciones pierden precisión. Es la tarea de mantenimiento más importante del contador: cinco minutos por mes."]}, {"t": "h2", "txt": "8.7 · Solapa 4 — Situación fiscal"}, {"t": "p", "txt": "Categoriza a cada anestesiólogo por sus ingresos brutos devengados de los últimos doce meses contra los topes de la escala de monotributo por locación de servicios. La tabla muestra CUIT, condición frente al IVA, devengado y cobrado de doce meses, categoría, uso del tope, margen que queda y una <b>proyección</b>: <i>Estable</i>, <i>Iría a la categoría X</i> —calculada al ritmo de los últimos tres meses— o <i>Fuera de escala</i>."}, {"t": "p", "txt": "Debajo, «Situaciones a resolver» las enumera en texto: quién superó el tope y debería evaluar el pase a responsable inscripto, quién usó más del 90 % de su categoría, quién debería anticipar la recategorización, y a quién le falta el CUIT o la condición frente al IVA."}, {"t": "p", "txt": "Cierran la solapa un <b>calendario de obligaciones</b> —cuota del monotributo, recategorización semestral, IVA, Ingresos Brutos, anticipos y declaración jurada de Ganancias, Bienes Personales y Libro IVA Digital— y una tabla de <b>retenciones</b> a considerar. El calendario es un recordatorio de qué hay que presentar, no un almanaque de fechas: los vencimientos concretos los fija ARCA cada año."}, {"t": "h2", "txt": "8.8 · Solapa 5 — Recomendaciones"}, {"t": "p", "txt": "No es texto fijo: se genera con los datos cargados. Aparecen sólo las que corresponden, y cada una viene con el importe y la cantidad de prestaciones involucradas."}, {"t": "tabla", "head": ["Se dispara cuando…", "Qué recomienda"], "rows": [["Hay deuda, pasado el umbral de mora", "Intimación por medio fehaciente: corta la prescripción, deja constancia y habilita el reclamo de intereses"], ["Hay deuda de más de 180 días", "Gestión intensiva: nota a la gerencia del financiador, mesa de trabajo con la institución y, sin respuesta, evaluar la vía judicial"], ["Hay deuda de más de un año", "Evaluar la previsión por incobrabilidad, que requiere respaldo documentado de las gestiones de cobro"], ["Un saldo perdió más del 10 % por inflación", "Reclamar el ajuste por IPC o usar el número para renegociar el valor de la unidad hacia adelante"], ["Un financiador cobró menos del 50 % de lo devengado", "Revisar el convenio: plazos, penalidad por mora y ajuste automático"], ["Hay prestaciones facturadas sin N.º de comprobante", "Pedirle al anestesiólogo que complete el dato: sin él no se concilia el cobro ni se respalda la deducción"], ["Hay prestaciones que nunca se presentaron", "Es lo primero a destrabar: el plazo del financiador recién arranca cuando se presenta"], ["Faltan meses de IPC o la escala fiscal está sin confirmar", "Cargarlos, porque el resto del portal se apoya en esos dos datos"]]}, {"t": "p", "txt": "Cierra con una tabla de criterio general para indexar, por tramo de pérdida acumulada, y con el botón <b>Comunicar estas conclusiones</b>, que abre un hilo con la coordinación titulado «Informe de cobranzas y situación fiscal»."}, {"t": "aviso", "clase": "info", "tit": "<b>Son un apoyo, no un dictamen</b>", "cuerpo": ["La propia pantalla lo aclara: las recomendaciones se generan a partir de los datos cargados y no reemplazan la decisión profesional del contador. Cada situación concreta exige su propio análisis."]}, {"t": "h2", "txt": "8.9 · Solapa 6 — Parámetros"}, {"t": "p", "txt": "Es lo único que el contador escribe, y de acá sale todo lo que calculan las otras cinco solapas. Tres bloques:"}, {"t": "h3", "txt": "Índice de precios al consumidor"}, {"t": "p", "txt": "Se carga mes a mes: mes, variación porcentual, botón <b>Cargar mes</b>. La tabla de abajo muestra la serie con su acumulado de doce meses y permite borrar un mes mal cargado. Al guardar, la serie <b>se replica a todos los dispositivos de la asociación</b>: se carga una sola vez, no una por equipo."}, {"t": "p", "txt": "La aplicación trae una serie de referencia precargada y avisa que es de referencia hasta que se verifique contra la publicación del INDEC."}, {"t": "h3", "txt": "Escala del monotributo"}, {"t": "p", "txt": "Un campo para identificar la escala en uso —por ejemplo «Escala vigente desde enero de 2026»— y la tabla de categorías editable: tope anual de ingresos brutos, impuesto integrado, SIPA y obra social, con la cuota total calculada sola."}, {"t": "p", "txt": "Las escalas se actualizan por semestre. Mientras no se reemplace la de referencia, el portal lo avisa en rojo en la solapa fiscal y las categorías que muestra son orientativas."}, {"t": "h3", "txt": "Alícuotas y plazos"}, {"t": "tabla", "head": ["Parámetro", "Para qué se usa"], "rows": [["<b>IVA general y IVA salud</b>", "Calendario de obligaciones y retenciones"], ["<b>Ingresos Brutos</b>", "Alícuota provincial, Tierra del Fuego"], ["<b>Retención de Ganancias y de IVA</b>", "Tabla de retenciones a considerar"], ["<b>Plazo de pago normal (días)</b>", "Debajo de esto una prestación no se considera atrasada"], ["<b>Mora a partir de (días)</b>", "Umbral de la deuda «morosa» en Cartera"], ["<b>Incobrable a partir de (días)</b>", "Umbral de la deuda «incobrable» y de la previsión"]]}, {"t": "p", "txt": "Cada guardado de esta solapa queda registrado en la auditoría, con el nombre de quien lo hizo."}, {"t": "img", "src": "manual/m11.jpg"}, {"t": "h2", "txt": "8.10 · Las dos bandejas de documentación"}, {"t": "p", "txt": "El anestesiólogo le manda al contador la documentación que respalda cada honorario, y llega a dos bandejas separadas:"}, {"t": "p", "txt": "En la vista previa de cada envío, antes del honorario, figura ahora el <b>carácter</b> —de la consulta o del acto, según cuál se mande— y, cuando no es programado, dice <b>«con adicional»</b>. Es de donde sale el recargo de urgencia y es lo primero que mira una auditoría que lo discute."}, {"t": "li", "num": false, "txt": "<b>Valoración </b><b>pre-anestésica</b> — con el honorario de la consulta discriminado."}, {"t": "li", "num": false, "txt": "<b>Ficha anestésica y parte quirúrgico</b> — con el honorario del acto discriminado renglón por renglón: base, adicionales del nomenclador y total."}, {"t": "p", "txt": "Cuando los dos actos médicos son del mismo profesional, al firmar puede mandar los dos de una vez con <b>«Enviar valoración + acto»</b>. Igual llegan <b>separados, uno a cada bandeja</b>, con su honorario discriminado: es como se facturan. Lo que cambió es que se mandan en un solo gesto, no que se mezclen."}, {"t": "p", "txt": "Desde ahí el contador puede reenviar el expediente completo a la auditoría médica de un financiador cuando lo pide."}, {"t": "aviso", "clase": "danger", "tit": "<b>Esta cesión la decide el profesional tratante, envío por envío</b>", "cuerpo": ["Los envíos a contaduría contienen nombre y DNI del paciente, la cirugía y el diagnóstico: son la rama más sensible de la base de datos. El contable ve esos documentos porque el tratante se los cedió para facturar y para responder auditorías, no por tener acceso general a la historia clínica. Es la única excepción a la regla del punto 8.1, y es una excepción deliberada, acotada y trazable."]}, {"t": "h2", "txt": "8.x · Los actos con más de un procedimiento"}, {"t": "p", "txt": "Cuando en un mismo acto anestésico se hizo más de una cirugía, la exportación al contador trae dos columnas nuevas: <b>Procedimientos</b>, con todos los nombres, y <b>Detalle 100/75/50 %</b>, con el renglón por renglón de dónde salió cada unidad anestésica: <i>«Colecistectomía laparoscópica 20 UA al 100 % = 20,00 UA | Gastrostomía 12 UA al 75 % = 9,00 UA»</i>."}, {"t": "p", "txt": "La regla que aplica la aplicación es la del nomenclador: el procedimiento de mayor complejidad al <b>100 %</b>, cada procedimiento adicional al <b>75 %</b> si su vía de abordaje difiere de la del principal y al <b>50 %</b> si la comparte. La columna <b>UA</b> que ya existía sigue significando lo mismo —las unidades que multiplican el valor de la unidad— sólo que ahora, cuando hay varios procedimientos, es la suma de las de cada uno <b>ya afectadas por su porcentaje</b>. El importe se calcula igual que siempre."}]}, {"n": "9", "tit": "Alcances: qué hace la aplicación", "ico": "lista", "coord": false, "b": [{"t": "tabla", "head": ["Módulo", "Qué resuelve"], "rows": [["<b>Valoración prequirúrgica</b>", "11 puntos con tarjeta exprés de seis esenciales, autocompletado de las escalas desde lo ya cargado, cuatro plantillas, conclusión redactada sola, 8 escalas calculadas, plan anestésico con 80 opciones de analgesia postoperatoria y consentimiento informado firmado"], ["<b>Precarga del paciente</b>", "Dos puertas para que el paciente cargue su ficha antes de venir: por invitación del anestesiólogo, o abierta desde una dirección pública con foto del ticket del turno. Bandeja en forma de agenda por institución y día. Nada entra a la historia clínica sin revisión campo por campo"], ["<b>Registro del acto</b><b> anestésico</b>", "Tiempos, técnica, vía aérea, drogas por peso, signos vitales con gráfico y con el significado de cada sigla, <b>balance hídrico con plan de fluidos propuesto</b>, <b>eventos con los más probables ordenados arriba</b> y lista OMS"], ["<b>Recuperación</b>", "Aldrete modificado, dolor EVA, náuseas, destino"], ["<b>Cierre</b><b> del acto anestésico</b>", "Firma digital, foja quirúrgica adjunta, documento final. La valoración y el acto se bajan por separado o juntos, y se eliminan por separado con cuenta regresiva de 2 h"], ["<b>Vademécum</b>", "Adultos y pediatría, 64 fármacos en 13 grupos, cálculo por peso con confirmación obligatoria"], ["<b>Nomenclador</b>", "1.477 prácticas anestésicas, 19 grupos, complejidades, Grilla B, 10 adicionales y 6 modalidades"], ["<b>Guías y protocolos</b>", "15 guías: vía aérea difícil, LAST, hipertermia maligna, anafilaxia, ASRA, ayuno, OMS, ERAS, entre otras"], ["<b>Calculadoras</b>", "Dosis por peso, fluidos, sangrado permisible, rescate lipídico, dantrolene"], ["<b>Facturación</b>", "Mensual por financiador, institución y modalidad. Exporta a Excel y PDF"], ["<b>Estadísticas</b>", "Por día, semana, mes, año o rango, cruzadas por institución, financiador, cirugía, especialidad, ASA, técnica y eventos"], ["<b>Envío al paciente</b>", "Tres PDF separados por correo, con membrete y pie legal"], ["<b>Envío a contaduría</b>", "Dos bandejas con el honorario discriminado y el parte quirúrgico. El acto solo, o valoración y acto en dos envíos de un gesto"], ["<b>Comunicación interna</b>", "Hilos con tipo, prioridad y control de respuesta a las 2 horas"], ["<b>Auditoría</b>", "Registro de accesos y cambios, archivado en Drive"], ["<b>Baja de una ficha</b>", "Cada profesional elimina sólo lo que actuó, con motivo asentado en auditoría y cuenta regresiva de 2 h con alarma a los 5 minutos"]]}, {"t": "h2", "txt": "Funciona sin conexión"}, {"t": "p", "txt": "Si se corta internet, la aplicación sigue funcionando: guarda todo en el dispositivo y sincroniza sola cuando vuelve la señal. En un quirófano con mala cobertura esto es determinante."}]}, {"n": "10", "tit": "Seguridad: qué protege y qué no", "ico": "candado", "coord": false, "b": [{"t": "tabla", "head": ["Aspecto", "Estado"], "rows": [["<b>Contraseñas de los socios</b>", "Guardadas con hash SHA-256, no en texto plano. Correcto"], ["<b>Base de datos</b>", "Cerrada: exige un pase de Firebase para leer o escribir. Correcto"], ["<b>Aprobación de altas por la coordinación</b>", "Sí. Nadie se auto-habilita"], ["<b>Acceso por intervención</b>", "Cada socio ve sólo los pacientes en los que actuó. Correcto"], ["<b>Registro de auditoría</b>", "Sí, con archivado permanente en Drive"], ["<b>Portal contable sin datos clínicos</b>", "Sí, por proyección anonimizada de campos"], ["<b>Confidencialidad de los hilos internos</b>", "Sólo los participantes"], ["<b>Claves de coordinación y contable</b>", "ATENCIÓN: visibles en el código de la página"], ["<b>Clave del envío de correos</b>", "ATENCIÓN: visible en el código de la página"], ["<b>Pase a la base de datos</b>", "ATENCIÓN: es anónimo. Ver más abajo"], ["<b>Cifrado de los datos en reposo</b>", "No. Sólo el que ofrece Firebase de fábrica"]]}, {"t": "h2", "txt": "El punto débil que hay que entender"}, {"t": "p", "txt": "Hoy la base de datos se abre con cualquier pase anónimo, y ese pase lo puede pedir cualquiera que lea el código de la página, que es público."}, {"t": "p", "txt": "En concreto: alguien saca del código la clave de acceso y la dirección de la base, pide un pase anónimo —lo mismo que hace la aplicación— y con eso las reglas actuales le dan lectura y escritura de todo, historias clínicas incluidas."}, {"t": "p", "txt": "Cerrar las reglas no fue inútil: antes ni siquiera hacía falta el pase, alcanzaba con conocer la dirección de la base. Se subió un escalón real. Pero no es el escalón final."}, {"t": "p", "txt": "El arreglo de fondo es el <b>inicio de sesión real de </b><b>Firebase</b>: que cada socio se identifique contra Firebase con su propia cuenta y que las reglas exijan un usuario conocido, no cualquier anónimo. Está pendiente y agendado."}, {"t": "aviso", "clase": "danger", "tit": "<b>Mientras tanto</b>", "cuerpo": ["No difundir la dirección de la aplicación fuera de la asociación. Una vez que una dirección circula, no se puede volver atrás."]}, {"t": "h2", "txt": "Recomendaciones inmediatas"}, {"t": "li", "num": true, "txt": "Cambiar las claves de coordinación y del contable por otras propias."}, {"t": "li", "num": true, "txt": "No difundir la dirección pública fuera de la asociación hasta tener el inicio de sesión real de Firebase."}, {"t": "li", "num": true, "txt": "Descargar el respaldo JSON con regularidad y guardarlo cifrado."}, {"t": "li", "num": true, "txt": "Borrar los datos de demostración antes del primer paciente real."}, {"t": "li", "num": true, "txt": "Revisar la auditoría periódicamente."}, {"t": "h3", "txt": "Las dos ramas por donde escribe el paciente"}, {"t": "p", "txt": "Cuando un paciente completa su ficha —por invitación o por precarga abierta— <b>no escribe en la historia clínica</b>. Escribe en dos ramas aparte de la base, <b>afar-prellenado</b> y <b>afar-precargas</b>, que cuelgan de la raíz y no de <b>afar</b>. El navegador del paciente no tiene forma de llegar a la historia de nadie: la rama clínica ni siquiera está bajo su alcance."}, {"t": "li", "num": false, "txt": "Cada pedido vive bajo un <b>token de 32 caracteres al azar</b> que viaja en el enlace del correo. Con ese token se escribe ese pedido y ninguno más."}, {"t": "li", "num": false, "txt": "Cuando el paciente finaliza, o cuando un anestesiólogo toma la precarga, el enlace <b>deja de poder escribir</b>. A partir de ahí es historia clínica y la corrige un profesional."}, {"t": "li", "num": false, "txt": "Las precargas que nadie toma <b>se borran solas</b> a los 15 días del turno declarado."}, {"t": "aviso", "clase": "danger", "tit": "<b>Lo que sigue sin estar resuelto</b>", "cuerpo": ["La bandeja de precargados necesita que el profesional pueda <b>listar</b> la rama, y hoy la regla que lo permite es <b>auth != null</b> — donde ese <i>auth</i> es un pase <b>anónimo</b> que la aplicación consigue sola. Cualquiera que lea el index.html público puede pedir uno y listar esa rama.", "Esto <b>no lo introdujo la precarga</b>: la rama <b>afar</b>, con toda la historia clínica de la asociación, está expuesta de la misma manera desde antes y con muchos más datos. Pero es la función que vuelve urgente arreglarlo.", "La solución es una sola y ya está escrita en reglas-firebase.txt: que cada socio se identifique en Firebase con su propia cuenta y que la regla exija ese usuario en vez de cualquier anónimo. Con esa línea quedan cerradas las tres ramas de una vez."]}]}, {"n": "11", "tit": "Limitaciones y pendientes", "ico": "alerta", "coord": false, "b": [{"t": "h2", "txt": "Limitaciones actuales"}, {"t": "li", "num": false, "txt": "<b>No hay integración con sistemas hospitalarios.</b> No se conecta con el sistema de la institución ni con EVWEB. Todo se carga en la aplicación."}, {"t": "li", "num": false, "txt": "<b>El PDF lo genera Google, no la aplicación.</b> La aplicación manda el contenido y el conversor de Google devuelve el PDF. Si ese servicio no está publicado en la versión correcta, el envío al paciente se cancela con aviso."}, {"t": "li", "num": false, "txt": "<b>Tope de 40 correos por día</b> al paciente, para contener el daño si alguien encontrara la clave del servicio en el código."}, {"t": "li", "num": false, "txt": "Las claves de coordinación y contable <b>no son secretas</b> en sentido estricto."}, {"t": "li", "num": false, "txt": "Los datos <b>no están cifrados en reposo</b>, más allá de lo que cifra Firebase."}, {"t": "li", "num": false, "txt": "Los datos de demostración <b>no se sincronizan</b>: hay que cargarlos —y borrarlos— en cada equipo."}, {"t": "h2", "txt": "Pendientes, en orden de importancia"}, {"t": "li", "num": true, "txt": "<b>Inicio de sesión real de </b><b>Firebase</b><b>.</b> Es el arreglo de fondo del punto débil de seguridad. Agendado."}, {"t": "li", "num": true, "txt": "Cambiar las claves de coordinación y contable."}, {"t": "li", "num": true, "txt": "Limpiar 16 archivos sueltos que quedaron en la raíz del repositorio de una carga anterior. No afectan al funcionamiento; es orden."}, {"t": "li", "num": true, "txt": "Autorizar el permiso de Drive en el servicio de Google, que se pedirá la primera vez que se archive la auditoría."}, {"t": "aviso", "clase": "ok", "tit": "<b>Ya resueltos</b>, y medidos en el capítulo 12: la compresión de las firmas digitales y el fin de la carga de todas las fichas en cada dispositivo.", "cuerpo": []}, {"t": "aviso", "clase": "warn", "tit": "<b>Lo que hay que mirar de lo nuevo</b>", "cuerpo": ["<b>La vía de abordaje se propone, no se sabe.</b> La aplicación la reconoce en unas 1.040 de las 1.477 prácticas del nomenclador leyendo el nombre. En las 437 restantes queda «Sin declarar» y hay que elegirla: sin ese dato no se puede decidir entre el 75 % y el 50 %, y mientras tanto se propone el 75 %.", "<b>El preseteado de signos vitales es una ayuda de escritura.</b> Carga los valores esperables para ese paciente bajo anestesia; no mide nada. Lo que se asienta tiene que ser lo que se está viendo en el monitor. Los controles cargados así salen marcados NORMAL, justamente para que se distingan.", "<b>La regla del 75 y el 50 se aplica a todos los procedimientos adicionales por igual</b>, comparando cada uno contra el principal. Si algún convenio en particular liquida el tercero y siguientes con otro porcentaje, hay que corregir las unidades a mano en Honorarios.", "<b>Las plantillas y la conclusión redactada hay que leerlas.</b> Son texto generado a partir de lo cargado, no una valoración hecha. Lo que se firma es historia clínica."]}, {"t": "h3", "txt": "Que los pacientes se enteren de la dirección"}, {"t": "p", "txt": "La precarga abierta funciona, pero no se difunde sola. Hace falta una decisión de la asociación y de cada institución: un <b>QR en el ticket del turno</b>, un cartel en admisión, que lo diga la secretaria al dar el turno. Sin eso la función existe y no la usa nadie, y es lo único de esta lista que no se arregla escribiendo código."}]}, {"n": "12", "tit": "Capacidad", "ico": "stats", "coord": false, "b": [{"t": "h2", "txt": "¿Soporta 20 anestesiólogos y 30 cirugías por día?"}, {"t": "p", "txt": "<b>Respuesta corta: sí.</b> La app verificó el resultado simulando las 2.700 fichas de noventa días de trabajo. Todo lo que sigue son mediciones sobre la aplicación funcionando."}, {"t": "p", "txt": "<b>El escenario.</b> 20 anestesiólogos, 30 cirugías diarias, 250 días hábiles: 7.500 fichas por año."}, {"t": "h2", "txt": "Se midió"}, {"t": "p", "txt": "El peso real de las fichas de la aplicación. Una ficha firmada completa pesaba 140 KB, y su desglose es revelador:"}, {"t": "tabla", "head": ["Parte de la ficha", "Peso"], "rows": [["<b>Consentimiento (2 firmas: paciente y anestesiólogo)</b>", "92,8 KB"], ["<b>Firma de cierre del anestesiólogo</b>", "43,0 KB"], ["<b>Todo el contenido clínico</b>", "3,5 KB"]]}, {"t": "p", "txt": "Las firmas eran el <b>97 %</b> del peso de una ficha. Cada una pesaba unos 45 KB porque se guardaba como imagen PNG del lienzo completo, a resolución mucho mayor de la necesaria."}, {"t": "h3", "txt": "1. El peso de las firmas"}, {"t": "p", "txt": "Una firma se guardaba tal como salía del lienzo: en una pantalla retina, con el doble de píxeles de los que se ven, y con todo el recuadro incluido, aunque la firma ocupara un tercio. Ahora se recorta al trazo, se lleva a 300 píxeles de ancho y se unifica la tinta para que el formato PNG pueda comprimirla."}, {"t": "tabla", "head": ["", "Antes", "Ahora", "Mejora"], "rows": [["<b>Una firma</b>", "34,6 KB", "8,2 KB", "4,2 veces"], ["<b>Una ficha firmada completa</b>", "140 KB", "25,4 KB", "5,5 veces"]]}, {"t": "p", "txt": "Se comprobó además que la firma comprimida se sigue viendo bien en los PDF que recibe el paciente: se imprime a unos 4 cm y el trazo sale limpio, sin escalones."}, {"t": "h3", "txt": "2 y 3. La copia local y el pedido a la nube"}, {"t": "p", "txt": "Cada equipo se sincroniza en vivo con los últimos 90 días y el navegador guarda como mucho 2,2 MB de fichas, las más recientes. Lo anterior está entero en la nube y se trae solo al abrirlo, al pedir estadísticas de un período viejo o al elegir «todo el historial» en la pantalla de Fichas."}, {"t": "p", "txt": "El tope por peso hace falta además del de días: con 30 cirugías diarias, noventa días son 2.700 fichas, que no entran en los 5 MB del navegador por más acotada que esté la ventana. Con el tope de peso da igual el tamaño de la asociación."}, {"t": "h2", "txt": "La proyección, medida"}, {"t": "tabla", "head": ["Medida", "Antes", "Ahora"], "rows": [["<b>Peso por ficha firmada</b>", "140 KB", "25,4 KB"], ["<b>Un año de fichas en la nube</b>", "1,00 GB", "186 MB"], ["<b>Duración del plan gratuito (1 GB)</b>", "12 meses", "5,5 años"], ["<b>Guardado en el navegador</b>", "Se llenaba en 1,2 días", "2,2 MB, fijos"], ["<b>Descarga al abrir la aplicación</b>", "1.025 MB", "67 MB"], ["<b>Descarga mensual (1.200 aperturas)</b>", "1.202 GB", "78 GB"]]}, {"t": "h2", "txt": "La prueba de estrés"}, {"t": "p", "txt": "Se simularon 2.722 fichas firmadas —noventa días a treinta cirugías diarias— dentro de la aplicación, y se midió cada pantalla:"}, {"t": "tabla", "head": ["Operación", "Tiempo"], "rows": [["<b>Escribir la base en el navegador</b>", "19 ms · aceptada, 2,24 MB"], ["<b>Listado de fichas</b>", "83 ms"], ["<b>Listado con todo el historial</b>", "63 ms"], ["<b>Panel de inicio</b>", "16 ms"], ["<b>Estadísticas del mes</b>", "7 ms"], ["<b>Facturación del mes</b>", "41 ms"], ["<b>Abrir una ficha y recorrer sus cinco pasos</b>", "42 ms"], ["<b>Generar los tres PDF del paciente</b>", "1 ms"]]}, {"t": "p", "txt": "Ninguna operación pasó de una décima de segundo, y el navegador aceptó la escritura sin acercarse a su límite."}, {"t": "h2", "txt": "Lo que queda por resolver"}, {"t": "p", "txt": "La descarga mensual sigue por encima del plan gratuito de Firebase, que da 10 GB. Con el volumen máximo proyectado serían unos 78 GB por mes, <b>del orden de 78 dólares mensuales en el plan </b><b>Blaze</b>: proporcionado a una asociación que hace 7.500 cirugías al año."}, {"t": "p", "txt": "Si se quisiera bajar aún más, la palanca es la ventana de días: es una sola constante en el código. <b>Con 30 días en vez de 90, la descarga mensual baja a unos 26 GB</b><b> con valor de 26 dólares</b><b>; con 15 días, a 13 GB</b><b> con valor de 13 dólares</b>. <i>El costo de acortarla es que haya que traer de la nube más seguido las fichas de consulta, algo que ocurre en un segundo y que la aplicación ya resuelve sola</i>."}, {"t": "p", "txt": "Para el tamaño actual de la asociación, todo entra holgado en el plan gratuito."}, {"t": "h2", "txt": "Hasta dónde sirve"}, {"t": "tabla", "head": ["Escenario", "¿Anda?"], "rows": [["<b>2 a 4 anestesiólogos, pocas cirugías por semana</b>", "Sí, holgado, en el plan gratuito"], ["<b>5 a 8 anestesiólogos, 3 a 5 cirugías diarias</b>", "Sí, en el plan gratuito"], ["<b>10 a 15, unas 15 cirugías diarias</b>", "Sí. Conviene mirar el consumo de descarga"], ["<b>20 anestesiólogos, 30 cirugías diarias</b>", "Sí, con plan Blaze (del orden de USD 78/mes)"]]}, {"t": "h2", "txt": "La auditoría, está resuelta"}, {"t": "p", "txt": "Con ese mismo volumen se generan unos 100.000 eventos por año, que son 16 MB. El dispositivo guarda los últimos 5.000 —0,8 MB— y todo lo anterior se archiva en Drive como planilla CSV. No se pierde nada y no crece en el equipo. Este módulo sí escala."}]}, {"n": "13", "tit": "Marco legal", "ico": "archivo", "coord": false, "b": [{"t": "tabla", "head": ["Norma", "Qué exige y cómo se cumple"], "rows": [["<b>Ley 26.529 y Ley 26.742 — Derechos del paciente</b>", "Consentimiento informado por escrito para todo procedimiento con riesgo relevante: es el punto 11 y es obligatorio. Derecho a revocarlo: está previsto y se documenta. La historia clínica pertenece al paciente y se le entrega copia: son los tres PDF"], ["<b>Decreto 1089/2012 y art. 59 del Código Civil y Comercial</b>", "Contenido y forma del consentimiento informado: los once apartados del texto"], ["<b>Ley 17.132 — Ejercicio de la medicina</b>", "Secreto profesional: acceso por intervención, y el contable sin datos clínicos"], ["<b>Ley 25.326 — Protección de datos personales</b>", "Datos de salud como datos sensibles: base cerrada, trazabilidad por auditoría, y derecho de acceso y rectificación informado al paciente en cada documento"]]}, {"t": "p", "txt": "<b>Conservación mínima:</b> diez años desde la última actuación (Ley 26.529, art. 18). Los respaldos JSON y los archivos de auditoría en Drive son parte de ese deber de conservación."}]}, {"n": "14", "tit": "Anexo — dónde está cada cosa", "ico": "nube", "coord": true, "b": [{"t": "aviso", "clase": "warn", "tit": "<b>Material de coordinación</b>", "cuerpo": ["Este anexo describe la infraestructura y explica cómo llegar a la base de datos y al respaldo completo. En la versión del manual que se reparte a todos los socios conviene retirarlo: mientras el punto débil del capítulo 10 siga abierto, cuanta menos gente conozca la dirección de la consola, mejor."]}, {"t": "p", "txt": "Los datos <b>no</b> están en Google Drive. Están en <b>Firebase</b><b>--</b><b>Realtime</b><b> </b><b>Database</b>, que es otro producto de Google. En Drive se guardan únicamente los archivos de auditoría."}, {"t": "tabla", "head": ["Qué", "Dónde vive", "Cómo se entra"], "rows": [["Todos los datos — socios, pacientes, fichas, valoraciones, consentimientos, firmas, mensajes y envíos", "Firebase Realtime Database, proyecto afar-anestesia", "Consola de Firebase"], ["Archivos de auditoría — los CSV con el registro de accesos y cambios", "Google Drive de la cuenta de AFAAR, carpeta «AFAAR — Auditoría»", "drive.google.com"], ["Correos enviados a pacientes, con los tres PDF adjuntos", "Gmail de la cuenta de AFAAR, carpeta Enviados", "gmail.com"], ["El programa que manda los correos y archiva la auditoría", "Google Apps Script", "script.google.com"], ["El código de la aplicación — no contiene ningún dato de pacientes", "GitHub Pages", "github.com/claudioravasi-ai/afar"], ["Copia de trabajo — los últimos 90 días, para trabajar sin conexión", "El navegador de cada equipo", "No se entra: es interna"]]}, {"t": "h2", "txt": "Las ramas de la base"}, {"t": "p", "txt": "El contenido cuelga de una rama llamada «afar» y se abre por partes:"}, {"t": "tabla", "head": ["Rama", "Qué contiene", "Rama", "Qué contiene"], "rows": [["usuarios", "Los anestesiólogos, con matrícula y datos fiscales", "archivos", "Fotos de partes quirúrgicos y adjuntos"], ["pacientes", "El padrón de la asociación", "auditoria", "Los últimos 5.000 eventos"], ["fichas", "Valoraciones y actos anestésicos", "mensajes", "La comunicación interna"], ["instituciones", "Hospitales, sanatorios y clínicas", "config", "Valores de unidad y sincronización"], ["obrasSociales", "Financiadores, con el valor de la unidad", "fiscal", "Parámetros de monotributo e índices"], ["envios", "Lo que cada profesional mandó a contaduría", "", ""]]}, {"t": "h2", "txt": "Tres cosas que conviene saber"}, {"t": "h3", "txt": "Para mirar los datos, no uses la consola de Firebase"}, {"t": "p", "txt": "La consola muestra el contenido en formato JSON crudo: sirve para verificar que algo llegó, pero es incómoda de leer. Y sobre todo es peligrosa: desde ahí se borra una rama entera con un clic, sin confirmación y sin papelera de reciclaje."}, {"t": "p", "txt": "Para revisar los datos con comodidad, entrá a la aplicación con la credencial de coordinación y usá el portal de Coordinación."}, {"t": "h3", "txt": "Si querés una copia completa, bajala desde la aplicación"}, {"t": "p", "txt": "Tocá el indicador «En línea» del encabezado y elegí <b>Descargar respaldo</b>. Te baja un archivo JSON con absolutamente todo. Ese respaldo contiene historias clínicas: guardalo cifrado, nunca en una carpeta compartida abierta ni en el repositorio público."}, {"t": "h3", "txt": "Firebase y Drive tienen espacios separados"}, {"t": "tabla", "head": ["", "Espacio gratuito", "Qué guarda", "Cuánto dura"], "rows": [["<b>Firebase</b>", "1 GB", "Todos los datos de la aplicación", "Años, con el peso actual de las fichas"], ["<b>Google Drive</b>", "15 GB en una cuenta común", "Sólo los CSV de auditoría, de 250 KB cada uno", "Décadas"]]}, {"t": "p", "txt": "Son cuentas de almacenamiento distintas: que se llene una, no afecta a la otra. Por el lado de Drive no hay problema en muchos años."}, {"t": "p", "txt": "AFAAR — Asociación Fueguina de Anestesia, Analgesia y Reanimación"}, {"t": "p", "txt": "Tierra del Fuego, Antártida e Islas del Atlántico Sur — República Argentina"}, {"t": "p", "txt": "Documento generado en agosto de 2026 sobre el build 2026.08.30.0910 de la aplicación."}, {"t": "p", "txt": "Las mediciones de capacidad del capítulo 12 se tomaron directamente de la aplicación en funcionamiento."}, {"t": "h2", "txt": "Archivos de las funciones nuevas"}, {"t": "tabla", "head": ["Qué", "Dónde"], "rows": [["Vías de abordaje y su detección por el nombre de la práctica", "<code>src/data-catalogos.js</code> — <code>VIAS_ABORDAJE</code>, <code>viaSugerida()</code>"], ["Regla 100 / 75 / 50 % y unidades efectivas", "<code>src/core.js</code> — <code>procedimientosFacturables()</code>, <code>uaEfectivas()</code>"], ["Valores vitales normales por franja etaria", "<code>src/core.js</code> — <code>FRANJAS_VITALES</code>, <code>vitalesNormalesDe()</code>"], ["Autocompletado, ASA propuesto y conclusión redactada", "<code>src/valoracion-auto.js</code>"], ["Tarjeta exprés y plantillas", "<code>src/ui-valoracion.js</code> — <code>htmlValoracionExpres()</code>, <code>PLANTILLAS_VAL</code>"], ["Cartel de faltantes en vivo y navegable", "<code>src/ui-ficha.js</code> — <code>refrescarFaltantes()</code>, <code>fichaEnPantalla()</code>; <code>src/ui-avisos.js</code> — <code>faltantesFicha()</code>"], ["Analgesia postoperatoria agrupada", "<code>src/data-catalogos.js</code> — <code>ANALGESIA_POP_GRUPOS</code>"]]}]}];
